// Helper — retorna config do tipo, com fallback para Residencial
function getTipoConfig(tipo) {
  const key = tipo === "Clínica" ? "Clinica"
            : tipo === "Galpão"  ? "Galpao"
            : (tipo || "Residencial");
  return TIPO_CONFIG[key] || TIPO_CONFIG.Residencial;
}

// ═══════════════════════════════════════════════════════════════
// PREÇO BASE DINÂMICO (Sprint 3 — modelo CUB)
// ═══════════════════════════════════════════════════════════════
// Calcula o preço base por m² de arquitetura usando:
//   precoBase = pct_efetivo × CUB[estado][R-1][padrão_normalizado]
//
// pct_efetivo: pct_calibrado se preenchido (calibragem pessoal do usuário),
//              senão pct_matriz_calculado (calculado pelo onboarding).
//
// Padrão do PROJETO ("Alto", "Médio", "Baixo") → padrão do CUB ("Alto", "Normal", "Baixo")
// Mapeamento: Médio → Normal (oficial NBR 12721, mas UI mostra "Médio").
//
// Empresas SEM onboarding completo (sem usuario.pct_*  ou sem data.cub):
//   → fallback pro precoBase fixo do TIPO_CONFIG (R$ 45 / R$ 32).
//
// Parâmetros:
//   tipoProjeto: "Residencial", "Clínica", "Conj. Comercial", "Galpão"
//   padrao:      "Alto" | "Médio" | "Baixo" (padrão do projeto, NÃO do CUB)
//   usuario:     objeto do JWT (com pct_calibrado, pct_matriz_calculado, estado)
//   cub:         data.cub do loadAllData (objeto { estado, Baixo, Normal, Alto })
//
// Retorna: { precoBase, modo } — modo "dinamico" ou "fixo"
// ═══════════════════════════════════════════════════════════════
// O CUB muda todo mês. Um orçamento feito em março com o CUB de janeiro não
// está errado — mas quem olha a proposta seis meses depois precisa saber de
// quando é o número, ou não tem como refazer a conta.
function mesDoCub(d) {
  if (!d) return "";
  const t = String(d).slice(0, 7).split("-");
  if (t.length < 2) return "";
  const meses = ["Jan","Fev","Mar","Abr","Mai","Jun","Jul","Ago","Set","Out","Nov","Dez"];
  const m = meses[parseInt(t[1], 10) - 1];
  return m ? `${m}/${t[0]}` : "";
}

function getPrecoBaseDinamico(tipoProjeto, padrao, usuario, cub, pavimentos) {
  const tcfg = getTipoConfig(tipoProjeto === "Clínica" ? "Clinica"
                          : tipoProjeto === "Galpão" ? "Galpao"
                          : (tipoProjeto || "Residencial"));
  const fallback = { precoBase: tcfg.precoBase, modo: "fixo" };

  // DEBUG: mostra o objeto usuario completo
  console.log("[getPrecoBaseDinamico] usuario completo:", usuario);
  console.log("[getPrecoBaseDinamico] cub existe?", !!cub, "cub:", cub);
  if (!usuario || !cub) {
    console.log("[getPrecoBaseDinamico] FALHOU: usuario=", !!usuario, "cub=", !!cub);
    return fallback;
  }
  const pct = (usuario.pct_calibrado != null && usuario.pct_calibrado > 0)
    ? usuario.pct_calibrado
    : usuario.pct_matriz_calculado;
  if (!pct || pct <= 0) return fallback;

  // Seleciona categoria de CUB por tipo de projeto
  // Mapeia padrão projeto (Baixo/Médio/Alto) → padrão CUB
  let categoriaCub = null;
  let padraoCub = padrao === "Médio" ? "Normal" : padrao;  // Médio → Normal (NBR 12721)

  if (tipoProjeto === "Conj. Comercial") {
    categoriaCub = cub.CSL8;  // CSL-8 para salas comerciais
    // CSL-8 só tem Normal e Alto; Baixo fallback para Normal
    if (padraoCub === "Baixo") padraoCub = "Normal";
  } else if (tipoProjeto === "Galpão") {
    categoriaCub = cub.GI;    // GI para galpão
    padraoCub = "Unico";      // GI tem apenas padrão único
  } else if (tipoProjeto === "Empreendimento") {
    // Até 4 pavimentos o CUB é o PP-4 (Prédio Popular); acima, o R-8. São
    // prédios diferentes: elevador, estrutura e instalações mudam de porte, e
    // o CUB acompanha. O PP-4 só tem Baixo e Normal — Alto cai em Normal;
    // o R-8 tem os três.
    const chave = cubDePavimentos(pavimentos);
    categoriaCub = chave === "R8" ? cub.R8 : cub.PP4;
    if (chave === "PP4" && padraoCub === "Alto") padraoCub = "Normal";
  } else {
    categoriaCub = cub.R1;    // R-1 para Residencial, Clínica
  }

  const cubObj = categoriaCub ? categoriaCub[padraoCub] : null;
  if (!cubObj || !cubObj.valor_m2 || cubObj.valor_m2 <= 0) return fallback;

  const precoBase = Math.round(pct * cubObj.valor_m2 * 100) / 100;
  const categoria = categoriaCub === cub.R1 ? "R-1"
                  : categoriaCub === cub.CSL8 ? "CSL-8"
                  : categoriaCub === cub.PP4 ? "PP-4"
                  : categoriaCub === cub.R8 ? "R-8" : "GI";
  console.log(`[PREÇO BASE] ${tipoProjeto} ${padrao} → ${categoria} ${padraoCub} | pct=${pct.toFixed(4)} × CUB=${cubObj.valor_m2.toFixed(2)} = R$ ${precoBase.toFixed(2)}/m²`);
  return { precoBase, modo: "dinamico", pct, cubM2: cubObj.valor_m2, padraoCub, categoria,
    mesCub: mesDoCub(cubObj.mes_referencia), fonteCub: cubObj.fonte || "",
    estadoCub: cub.estado || cubObj.estado || "" };
}
var fmt = (v) => (v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
var fmtM2 = (v) => `${(v||0).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2})} m²`;
var fmtA  = (v, dec=2) => (v||0).toLocaleString("pt-BR",{minimumFractionDigits:dec,maximumFractionDigits:dec});

// ═══════════════════════════════════════════════════════════════
// SEED DATA
// Fallback vazio usado apenas quando o backend está offline.
// Dados reais vêm exclusivamente do banco via loadAllData().
// ═══════════════════════════════════════════════════════════════
var SEED = {
  clientes:           [],
  fornecedores:       [],
  materiais:          [],
  lancamentos:        [],
  obras:              [],
  orcamentosProjeto:  [],
  escritorio:         {},
  receitasFinanceiro: [],
};

var ESTADOS_BR = ["AC","AL","AM","AP","BA","CE","DF","ES","GO","MA","MG","MS","MT","PA","PB","PE","PI","PR","RJ","RN","RO","RR","RS","SC","SE","SP","TO"];
var CATS_FORNECEDOR = ["Cimento","Concreto","Agregados","Alvenaria","Estrutura","Cobertura","Elétrico","Hidráulico","Revestimento","Acabamento","Ferramentas","Tintas","Vidros","Geral","Outros"];

// ═══════════════════════════════════════════════════════════════
// SISTEMA DE DIÁLOGOS E TOASTS (substitui alert/confirm nativos)
// ═══════════════════════════════════════════════════════════════
// Rationale:
// - Diálogos nativos (alert/confirm) têm UX feia, mostram URL do site,
//   quebram o fluxo visual e não combinam com o design do VICKE.
// - Este sistema oferece 3 helpers globais chamáveis de qualquer função
//   (não só dentro de componentes React) pra facilitar migração:
//     toast.sucesso(msg)   → balão verde que some em 3s (avisos positivos)
//     toast.erro(msg)      → balão vermelho que some em 4s
//     dialogo.confirmar({titulo, mensagem, confirmar, destrutivo}) → Promise<boolean>
//     dialogo.alertar({titulo, mensagem, tipo}) → Promise<void>
//
// Arquitetura:
// - Estado vive num objeto _dialogState fora do React.
// - Listeners são callbacks registrados por DialogosHost.
// - DialogosHost é um componente renderizado uma vez no app.jsx que
//   desenha os modais/toasts ativos.
// ═══════════════════════════════════════════════════════════════

var _dialogState = {
  modais: [],      // { id, tipo: "confirm"|"alert", titulo, mensagem, confirmar, cancelar, destrutivo, tipoAlert, resolver }
  toasts: [],      // { id, tipo: "sucesso"|"erro", mensagem }
  listeners: new Set(),
  _nextId: 1,
};

function _dialogNotify() {
  _dialogState.listeners.forEach(fn => { try { fn(); } catch {} });
}

// API pública
var toast = {
  sucesso: (mensagem, duracao = 3000) => {
    const id = _dialogState._nextId++;
    _dialogState.toasts.push({ id, tipo: "sucesso", mensagem });
    _dialogNotify();
    setTimeout(() => {
      _dialogState.toasts = _dialogState.toasts.filter(t => t.id !== id);
      _dialogNotify();
    }, duracao);
  },
  erro: (mensagem, duracao = 4000) => {
    const id = _dialogState._nextId++;
    _dialogState.toasts.push({ id, tipo: "erro", mensagem });
    _dialogNotify();
    setTimeout(() => {
      _dialogState.toasts = _dialogState.toasts.filter(t => t.id !== id);
      _dialogNotify();
    }, duracao);
  },
};

var dialogo = {
  // Retorna Promise<boolean> — true se confirmou, false se cancelou.
  // Use async/await: const ok = await dialogo.confirmar({...});
  confirmar: (opts) => {
    return new Promise(resolver => {
      const id = _dialogState._nextId++;
      _dialogState.modais.push({
        id,
        tipo: "confirm",
        titulo: opts.titulo || "Confirmar?",
        mensagem: opts.mensagem || "",
        confirmar: opts.confirmar || "Confirmar",
        cancelar: opts.cancelar || "Cancelar",
        destrutivo: !!opts.destrutivo,
        resolver,
      });
      _dialogNotify();
    });
  },
  // Retorna Promise<void> — resolve quando usuário clica OK.
  alertar: (opts) => {
    return new Promise(resolver => {
      const id = _dialogState._nextId++;
      _dialogState.modais.push({
        id,
        tipo: "alert",
        titulo: opts.titulo || "",
        mensagem: opts.mensagem || "",
        confirmar: opts.confirmar || "OK",
        tipoAlert: opts.tipo || "info", // info | erro | sucesso | aviso
        resolver,
      });
      _dialogNotify();
    });
  },
};

// Host React: renderiza modais e toasts. Deve ser montado UMA VEZ
// no topo da app (app.jsx, dentro do root mas independente das telas).
function DialogosHost() {
  const [, forceRender] = useState(0);

  useEffect(() => {
    const fn = () => forceRender(n => n + 1);
    _dialogState.listeners.add(fn);
    return () => { _dialogState.listeners.delete(fn); };
  }, []);

  function fecharModal(id, valor) {
    const m = _dialogState.modais.find(x => x.id === id);
    if (!m) return;
    _dialogState.modais = _dialogState.modais.filter(x => x.id !== id);
    _dialogNotify();
    if (m.resolver) m.resolver(valor);
  }

  // Suporte a ESC pra fechar modal ativo (cancela em confirm, fecha em alert)
  useEffect(() => {
    const handler = (e) => {
      if (e.key !== "Escape") return;
      const m = _dialogState.modais[_dialogState.modais.length - 1];
      if (!m) return;
      fecharModal(m.id, m.tipo === "confirm" ? false : undefined);
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, []);

  const modais = _dialogState.modais;
  const toasts = _dialogState.toasts;
  const modalTopo = modais[modais.length - 1] || null;

  const coresAlert = {
    info:    { borda: "rgba(38,36,33,0.14)", texto: "#262421" },
    sucesso: { borda: "#bbf7d0", texto: "#15803d" },
    erro:    { borda: "#fecaca", texto: "#b91c1c" },
    aviso:   { borda: "#fde68a", texto: "#b45309" },
  };

  return (
    <>
      {/* Modal ativo — só renderiza o último da fila (topo) */}
      {modalTopo && (
        <div
          onClick={() => fecharModal(modalTopo.id, modalTopo.tipo === "confirm" ? false : undefined)}
          style={{
            position: "fixed", inset: 0,
            background: "rgba(0,0,0,0.4)",
            zIndex: 100000,
            display: "flex", alignItems: "center", justifyContent: "center",
            padding: 20,
            fontFamily: "'Inter', system-ui, -apple-system, sans-serif",
            animation: "vickeDialogFade 0.15s ease",
          }}
        >
          <div
            onClick={e => e.stopPropagation()}
            style={{
              background: "#fff",
              border: `1px solid ${modalTopo.tipo === "alert" ? (coresAlert[modalTopo.tipoAlert]?.borda || "rgba(38,36,33,0.14)") : "rgba(38,36,33,0.14)"}`,
              borderRadius: 16,
              padding: "24px 28px",
              maxWidth: 440,
              width: "100%",
              boxShadow: "0 20px 40px rgba(0,0,0,0.15)",
              animation: "vickeDialogPop 0.18s cubic-bezier(0.2, 0.7, 0.3, 1.1)",
            }}
          >
            {modalTopo.titulo && (
              <div style={{
                fontSize: 15,
                fontWeight: 700,
                color: modalTopo.tipo === "alert" ? (coresAlert[modalTopo.tipoAlert]?.texto || "#262421") : "#262421",
                marginBottom: modalTopo.mensagem ? 10 : 18,
              }}>
                {modalTopo.titulo}
              </div>
            )}
            {modalTopo.mensagem && (
              <div style={{
                fontSize: 13.5,
                color: "#4b5563",
                lineHeight: 1.55,
                marginBottom: 20,
                whiteSpace: "pre-wrap",
              }}>
                {modalTopo.mensagem}
              </div>
            )}
            <div style={{ display: "flex", gap: 10, justifyContent: "flex-end" }}>
              {modalTopo.tipo === "confirm" && (
                <button
                  onClick={() => fecharModal(modalTopo.id, false)}
                  style={{
                    background: "#fff",
                    color: "#4b5563",
                    border: "1.5px solid rgba(38,36,33,0.16)",
                    borderRadius: 12,
                    padding: "8px 18px",
                    fontSize: 13,
                    cursor: "pointer",
                    fontFamily: "inherit",
                  }}
                >
                  {modalTopo.cancelar}
                </button>
              )}
              <button
                autoFocus
                onClick={() => fecharModal(modalTopo.id, modalTopo.tipo === "confirm" ? true : undefined)}
                style={{
                  background: modalTopo.destrutivo ? "#dc2626" : "#262421",
                  color: "#fff",
                  border: "none",
                  borderRadius: 12,
                  padding: "8px 20px",
                  fontSize: 13,
                  fontWeight: 600,
                  cursor: "pointer",
                  fontFamily: "inherit",
                }}
              >
                {modalTopo.confirmar}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Toasts — pilha no canto superior direito. Recente embaixo. */}
      {toasts.length > 0 && (
        <div style={{
          position: "fixed",
          top: 20,
          right: 20,
          zIndex: 100001,
          display: "flex",
          flexDirection: "column",
          gap: 8,
          fontFamily: "'Inter', system-ui, -apple-system, sans-serif",
          pointerEvents: "none",
        }}>
          {toasts.map(t => (
            <div
              key={t.id}
              style={{
                background: "#fff",
                border: `1px solid ${t.tipo === "sucesso" ? "#bbf7d0" : "#fecaca"}`,
                borderLeft: `4px solid ${t.tipo === "sucesso" ? "#16a34a" : "#dc2626"}`,
                borderRadius: 12,
                padding: "10px 14px 10px 12px",
                fontSize: 13,
                color: t.tipo === "sucesso" ? "#15803d" : "#b91c1c",
                boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
                minWidth: 240,
                maxWidth: 360,
                display: "flex",
                alignItems: "center",
                gap: 8,
                fontWeight: 500,
                animation: "vickeToastSlide 0.24s cubic-bezier(0.2, 0.7, 0.3, 1.1)",
                pointerEvents: "auto",
              }}
            >
              <span style={{ fontSize: 14, flexShrink: 0 }}>
                {t.tipo === "sucesso" ? "✓" : "⚠"}
              </span>
              <span>{t.mensagem}</span>
            </div>
          ))}
        </div>
      )}

      <style>{`
        @keyframes vickeDialogFade { from { opacity: 0; } to { opacity: 1; } }
        @keyframes vickeDialogPop {
          from { opacity: 0; transform: translateY(-8px) scale(0.98); }
          to { opacity: 1; transform: translateY(0) scale(1); }
        }
        @keyframes vickeToastSlide {
          from { opacity: 0; transform: translateX(40px); }
          to { opacity: 1; transform: translateX(0); }
        }
      `}</style>
    </>
  );
}

// ═══════════════════════════════════════════════════════════════
// VERSION WATCHER — detecta novos deploys e avisa o usuário
// ═══════════════════════════════════════════════════════════════
// Problema resolvido: mesmo com vercel.json definindo no-cache pro HTML,
// uma sessão aberta há horas continua rodando o JS antigo. Quando o master
// faz npm run cpush, quem está com a app aberta não vê as mudanças até dar
// F5 — e pode cair em bugs como "escritório não aparece no PDF" porque
// o JS em memória não sabe da nova coluna que o backend já espera.
//
// Como funciona:
// 1. No boot, captura o hash do bundle principal (ex: "index-Bkt6z0GT.js")
//    lendo a própria <script type="module" src="/assets/index-XXXX.js"> do HTML.
// 2. A cada 5 min, faz fetch("/?v=timestamp") pra forçar bypass de cache
//    intermediário, lê o HTML retornado, extrai o hash atual do bundle.
// 3. Se o hash mudou → mostra banner persistente com botão "Atualizar".
//    O usuário clica → location.reload() com bypass de cache.
//
// Não reload automático: pode perder trabalho não salvo do usuário.
// Notificação + ação manual é o equilíbrio entre segurança e agilidade.
//
// IGNORA erros de rede silenciosamente: se o usuário está offline,
// o próximo check acaba funcionando. Não queremos poluir com avisos.
// ═══════════════════════════════════════════════════════════════

function _extrairHashBundle(htmlOuDoc) {
  // Aceita documento atual (document) ou string HTML crua do fetch.
  // Padrão: <script type="module" crossorigin src="/assets/index-HASH.js">
  // ou <script type="module" src="/assets/index-HASH.js">
  try {
    let src = "";
    if (typeof htmlOuDoc === "string") {
      const m = htmlOuDoc.match(/<script[^>]*src=["']([^"']*\/assets\/index-[^"']+\.js)["']/);
      src = m ? m[1] : "";
    } else {
      // document atual: procura a tag script que referenciou o bundle
      const scripts = htmlOuDoc.querySelectorAll('script[src*="/assets/index-"]');
      src = scripts.length > 0 ? scripts[0].getAttribute("src") : "";
    }
    if (!src) return null;
    // Extrai só o hash: "/assets/index-Bkt6z0GT.js" → "Bkt6z0GT"
    const h = src.match(/index-([^.]+)\.js/);
    return h ? h[1] : null;
  } catch {
    return null;
  }
}

function VersionWatcher() {
  const [novaVersao, setNovaVersao] = useState(false);
  const hashAtualRef = useRef(null);

  // Limpa o param `_v` da URL se ele existir.
  // Esse param é adicionado pelo botão "Atualizar" deste mesmo componente
  // como cache-buster do reload — depois do reload, ele fica grudado na
  // URL/histórico, o que é feio e desnecessário. Remove silenciosamente
  // sem disparar nova navegação (history.replaceState).
  useEffect(() => {
    try {
      const u = new URL(window.location.href);
      if (u.searchParams.has("_v")) {
        u.searchParams.delete("_v");
        const novaUrl = u.pathname + (u.searchParams.toString() ? "?" + u.searchParams.toString() : "") + u.hash;
        window.history.replaceState({}, "", novaUrl);
      }
    } catch {
      // URL inválida ou ambiente sem history API — ignora silenciosamente
    }
  }, []);

  useEffect(() => {
    // Captura hash inicial do bundle que está rodando agora
    hashAtualRef.current = _extrairHashBundle(document);

    // Se não conseguiu capturar (ex: dev mode sem bundling), desiste silenciosamente
    if (!hashAtualRef.current) return;

    let cancelado = false;

    async function verificar() {
      if (cancelado) return;
      try {
        // Query string quebra cache intermediário — garante que pegamos
        // o HTML mais novo do Vercel, não de proxy/CDN
        const res = await fetch("/?_vck=" + Date.now(), { cache: "no-store" });
        if (!res.ok) return;
        const html = await res.text();
        const hashRemoto = _extrairHashBundle(html);
        if (hashRemoto && hashRemoto !== hashAtualRef.current) {
          setNovaVersao(true);
        }
      } catch {
        // Rede caiu, etc. Ignora — próximo tick tenta de novo.
      }
    }

    // Primeira checagem 30s depois do boot (evita correr na hora do load)
    const t0 = setTimeout(verificar, 30_000);
    // Depois, a cada 5 minutos
    const interval = setInterval(verificar, 5 * 60 * 1000);

    // Re-checa quando a aba volta a ficar visível (usuário voltou depois de
    // horas, muito comum em SaaS) — a 5-min interval pode ter pulado checagem
    function onVisibility() { if (document.visibilityState === "visible") verificar(); }
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      cancelado = true;
      clearTimeout(t0);
      clearInterval(interval);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, []);

  if (!novaVersao) return null;

  return (
    <div
      role="alert"
      style={{
        position: "fixed",
        bottom: 20,
        right: 20,
        zIndex: 100002, // acima de toasts (100001) e modais (100000)
        background: "#262421",
        color: "#fff",
        padding: "14px 18px",
        borderRadius: 14,
        boxShadow: "0 8px 24px rgba(0,0,0,0.25)",
        display: "flex",
        alignItems: "center",
        gap: 14,
        fontFamily: "'Inter', system-ui, -apple-system, sans-serif",
        fontSize: 13,
        animation: "vickeToastSlide 0.28s cubic-bezier(0.2, 0.7, 0.3, 1.1)",
        maxWidth: 360,
      }}
    >
      <div style={{ flex: 1 }}>
        <div style={{ fontWeight: 600, marginBottom: 2 }}>Nova versão disponível</div>
        <div style={{ fontSize: 12, color: "#d1d5db" }}>Atualize para ver as últimas melhorias.</div>
      </div>
      <button
        onClick={() => {
          // reload(true) é deprecated — cache-busting via query string funciona
          const u = new URL(window.location.href);
          u.searchParams.set("_v", Date.now());
          window.location.href = u.toString();
        }}
        style={{
          background: "#fff",
          color: "#111827",
          border: "none",
          borderRadius: 7,
          padding: "7px 14px",
          fontSize: 12.5,
          fontWeight: 600,
          cursor: "pointer",
          fontFamily: "inherit",
          whiteSpace: "nowrap",
        }}
      >
        Atualizar
      </button>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// SESSION COORDINATOR — múltiplas abas, mesma origem
// ═══════════════════════════════════════════════════════════════
// Problema: localStorage é compartilhado entre TODAS as abas do mesmo
// domínio. Quando o usuário faz login na Aba B, o token salvo na Aba A
// é sobrescrito. Aba A continua com state em memória apontando pra
// usuário antigo, mas qualquer F5 ou bootstrap puxa o novo token →
// inconsistência (UI diz X, backend trata como Y).
//
// Solução: BroadcastChannel (API moderna, suportada em todos browsers
// relevantes) pra coordenar abas em tempo real. Quando uma aba muda
// estado de auth, todas as outras são notificadas e reagem:
//
// - Login com USUÁRIO IGUAL: aba antiga atualiza token silenciosamente.
//   Caso comum quando alguém abre uma 2ª aba pra "trabalhar em paralelo".
//   Sem fricção, sem reload — mesma sessão, token novo válido.
//
// - Login com USUÁRIO DIFERENTE: aba antiga mostra modal "Sessão alterada"
//   e força reload. Inevitável: a sessão atual não é mais válida pra
//   usuário X, e continuar usando geraria erros 403 imprevisíveis.
//
// - Logout: outras abas mostram "Você foi desconectado" e recarregam
//   (caem na tela de login).
//
// - Storage event como fallback: caso BroadcastChannel falhe (rara),
//   o evento `storage` do localStorage também dispara entre abas.
//
// O "líder" (aba atual) NÃO recebe mensagens que ela própria envia —
// API garante isso, então não há eco/loop.
// ═══════════════════════════════════════════════════════════════

const _SESSION_CHANNEL_NAME = "vicke-session";
let _sessionChannel = null;

function _getSessionChannel() {
  if (typeof BroadcastChannel === "undefined") return null;
  if (_sessionChannel) return _sessionChannel;
  try {
    _sessionChannel = new BroadcastChannel(_SESSION_CHANNEL_NAME);
  } catch {
    _sessionChannel = null;
  }
  return _sessionChannel;
}

// Anuncia evento de sessão pras outras abas. Chamar APÓS já ter
// atualizado localStorage (as outras abas vão ler de lá pra atualizar).
function anunciarSessao(tipo, payload) {
  const ch = _getSessionChannel();
  if (!ch) return;
  try {
    ch.postMessage({ tipo, payload, ts: Date.now() });
  } catch { /* canal pode estar fechado, ignora */ }
}

// Hook que aba consumidora usa pra reagir a mudanças vindas de outras abas.
// onOutroUsuario: outra aba logou com user diferente → exibir modal + reload
// onMesmoUsuario: outra aba logou com user igual → atualizar token em memória
// onLogout: outra aba fez logout → exibir modal "desconectado" + reload
function useSessionCoordinator({ usuarioAtual, onOutroUsuario, onMesmoUsuario, onLogout }) {
  useEffect(() => {
    const ch = _getSessionChannel();
    if (!ch) return; // browser sem BroadcastChannel — fallback storage event abaixo

    function handleMessage(ev) {
      const msg = ev.data || {};
      if (!msg.tipo) return;

      if (msg.tipo === "login") {
        const novoUserId = msg.payload?.userId;
        const usuarioIdAtual = usuarioAtual?.id;
        // Sem usuário em memória ainda? Não é nosso problema — ainda na tela de login
        if (!usuarioIdAtual) return;
        if (novoUserId === usuarioIdAtual) {
          onMesmoUsuario && onMesmoUsuario(msg.payload);
        } else {
          onOutroUsuario && onOutroUsuario(msg.payload);
        }
      } else if (msg.tipo === "logout") {
        // Só reagir se a aba atual estava logada
        if (usuarioAtual?.id) {
          onLogout && onLogout();
        }
      }
    }

    ch.addEventListener("message", handleMessage);

    // Fallback: evento `storage` do localStorage. Dispara em outras abas
    // quando o valor de uma chave muda. Útil se BroadcastChannel falhar
    // ou se o navegador for muito antigo.
    function handleStorage(ev) {
      if (ev.key !== "vicke-token" && ev.key !== "vicke-user") return;
      // Token foi removido em outra aba (logout)
      if (ev.key === "vicke-token" && !ev.newValue && usuarioAtual?.id) {
        onLogout && onLogout();
        return;
      }
      // User mudou em outra aba → comparar IDs
      if (ev.key === "vicke-user" && ev.newValue && usuarioAtual?.id) {
        try {
          const novoUser = JSON.parse(ev.newValue);
          if (novoUser?.id && novoUser.id !== usuarioAtual.id) {
            onOutroUsuario && onOutroUsuario({ userId: novoUser.id });
          } else if (novoUser?.id === usuarioAtual.id) {
            onMesmoUsuario && onMesmoUsuario({ userId: novoUser.id });
          }
        } catch { /* JSON ruim, ignora */ }
      }
    }
    window.addEventListener("storage", handleStorage);

    return () => {
      ch.removeEventListener("message", handleMessage);
      window.removeEventListener("storage", handleStorage);
    };
  }, [usuarioAtual?.id, onOutroUsuario, onMesmoUsuario, onLogout]);
}


// ═════════════════════════════════════════════════════════════
// SelectBusca — lista de seleção que abre com o campo de busca em cima
// ═════════════════════════════════════════════════════════════
// Etapa da obra são 53 opções; conta do P&L, 43. Num <select> nativo, achar
// "Reboco interno" é rolar a lista — e num pedido de vinte itens isso se
// repete vinte vezes. Aqui a lista abre com o cursor já dentro do campo de
// busca: digitou "reb", a opção certa já está marcada, Enter escolhe. Setas
// andam, Esc fecha, clique fora fecha, e uma letra digitada com o campo
// fechado abre a lista já filtrando.
//
// Aceita as formas que os módulos já têm em mão, para não obrigar ninguém a
// remontar a lista só para trocar o select:
//   ["m2", "un"]                              → valor = rótulo
//   [{ id, nome }] [{ valor, rotulo }] [{ value, label }]
//   [{ grupo: "Fundação", opcoes: [...] }]      → cabeçalho de grupo (optgroup)
//   [{ valor, rotulo, grupo }]                 → idem, já achatado
// O nome do grupo entra na busca: "fund sap" acha a sapata da fundação.

// ── SelectBusca: parte pura ────────────────────────────

// Ninguém digita "tábua" nem "cerâmica" com acento no meio de um pedido.
function buscaNormal(t) {
  return String(t == null ? "" : t)
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .toLowerCase().replace(/\s+/g, " ").trim();
}

// Achata qualquer das formas aceitas em { valor, rotulo, grupo, busca }.
function opcoesNormalizadas(opcoes) {
  const saida = [];
  (Array.isArray(opcoes) ? opcoes : []).forEach(function (o) {
    if (o == null) return;
    if (typeof o === "string" || typeof o === "number") {
      saida.push({ valor: String(o), rotulo: String(o), grupo: "", extra: "" });
      return;
    }
    if (Array.isArray(o.opcoes)) {
      const nomeGrupo = String(o.grupo || o.titulo || o.label || o.nome || "");
      opcoesNormalizadas(o.opcoes).forEach(function (f) {
        saida.push({ valor: f.valor, rotulo: f.rotulo, grupo: f.grupo || nomeGrupo, extra: f.extra });
      });
      return;
    }
    const valor = o.valor != null ? o.valor : (o.value != null ? o.value : (o.id != null ? o.id : ""));
    const rotulo = o.rotulo != null ? o.rotulo
      : (o.label != null ? o.label : (o.nome != null ? o.nome : String(valor)));
    saida.push({
      valor: String(valor),
      rotulo: String(rotulo),
      grupo: String(o.grupo != null ? o.grupo : (o.macro != null ? o.macro : "")),
      extra: String(o.extra != null ? o.extra : ""),
    });
  });
  return saida.map(function (o) {
    return {
      valor: o.valor, rotulo: o.rotulo, grupo: o.grupo, extra: o.extra,
      busca: buscaNormal([o.rotulo, o.grupo, o.extra].join(" ")),
      // O valor costuma ser um id ("1afw1za") ou um código ("CON-001"). Ele
      // não entra na busca por pedaço — senão o "1" de "módulo 1" achava o
      // Módulo 3 pelo id dele. Só vale quando o que se digitou É o começo
      // do código.
      buscaValor: buscaNormal(o.valor),
      buscaRotulo: buscaNormal(o.rotulo),
    };
  });
}

// Filtra por pedacos soltos ("reb int" acha "Reboco interno") e põe na frente
// quem COMEÇA com o que foi digitado — é essa a opção que a pessoa espera ver
// já marcada depois das primeiras letras.
// Número digitado casa com número inteiro, não com o meio de outro: "1"
// acha "Módulo 1" e "10 mm", mas não o "1" de "L21". Texto casa em qualquer
// lugar, como sempre ("eiro" acha serralheiro).
function casaPedaco(texto, p) {
  if (!/^\d/.test(p)) return texto.indexOf(p) >= 0;
  let i = texto.indexOf(p);
  while (i >= 0) {
    if (i === 0 || !/\d/.test(texto.charAt(i - 1))) return true;
    i = texto.indexOf(p, i + 1);
  }
  return false;
}

function filtrarOpcoes(lista, termo) {
  const alvo = buscaNormal(termo);
  if (!alvo) return lista;
  const partes = alvo.split(" ").filter(Boolean);
  // Na frente quem começa com o que foi digitado; depois quem tem tudo no
  // PRÓPRIO nome; por último quem só casou pelo grupo ou pelo apelido.
  const comeca = [], noNome = [], contem = [];
  lista.forEach(function (o) {
    const rot = o.buscaRotulo != null ? o.buscaRotulo : buscaNormal(o.rotulo);
    const pelaBusca = partes.every(function (p) { return casaPedaco(o.busca, p); });
    const peloCodigo = !!o.buscaValor && o.buscaValor.indexOf(alvo) === 0;
    if (!pelaBusca && !peloCodigo) return;
    if (rot.indexOf(alvo) === 0 || peloCodigo) comeca.push(o);
    else if (partes.every(function (p) { return casaPedaco(rot, p); })) noNome.push(o);
    else contem.push(o);
  });
  return comeca.concat(noNome, contem);
}

// O que não está na lista precisa poder entrar sem sair da lista. Quem já
// escreveu o nome na busca não deve escrevê-lo de novo num formulário: o
// que ele digitou é o nome, e o botão diz isso em vez de "cadastrar novo".
function rotuloDeCriar(termo, oQue) {
  const t = String(termo == null ? "" : termo).trim();
  const coisa = String(oQue || "").trim();
  if (t) return "＋ Cadastrar “" + t + "”";
  return coisa ? "＋ Cadastrar " + coisa : "＋ Cadastrar";
}

// ── SelectBusca: fim da parte pura ────────────────────

const SB_CAMPO = {
  border: "1px solid rgba(38,36,33,0.16)", borderRadius: 12, padding: "9px 12px",
  fontSize: 13, background: "#fff", fontFamily: "inherit", width: "100%",
  boxSizing: "border-box", outline: "none",
};

function SelectBusca(props) {
  const lista = useMemo(function () { return opcoesNormalizadas(props.opcoes); }, [props.opcoes]);
  const [aberto, setAberto] = useState(false);
  const [termo, setTermo] = useState("");
  const [marcado, setMarcado] = useState(0);
  const [caixa, setCaixa] = useState(null);
  const refBotao = useRef(null);
  const refBusca = useRef(null);
  const refPainel = useRef(null);
  // Lista curta não ganha campo de busca, mas continua respondendo às letras
  // como o select nativo: "fu" pula para a primeira opção que começa assim.
  const refDigitado = useRef({ texto: "", quando: 0 });
  // O ouvinte de clique fora é registrado uma vez; o ref mantém o fechar atual.
  const fecharRef = useRef(function () {});
  // O campo de busca só existe depois que o painel foi medido; por isso quem
  // põe o cursor nele é o próprio nascimento do campo, e não um temporizador
  // que pode disparar antes — ou depois de o clique devolver o foco ao corpo.
  const jaFocou = useRef(false);

  const valorAtual = props.value == null ? "" : String(props.value);
  const escolhida = lista.filter(function (o) { return o.valor === valorAtual; })[0];
  const filtradas = useMemo(function () { return filtrarOpcoes(lista, termo); }, [lista, termo]);
  // O catálogo de insumos passa de mil linhas: desenhar todas só para a
  // pessoa digitar três letras é trabalho jogado fora. Mostra as primeiras e
  // avisa que refinar a busca traz o resto.
  const teto = props.teto == null ? 200 : props.teto;
  const visiveis = useMemo(function () { return filtradas.slice(0, teto); }, [filtradas, teto]);
  // Um select de duas opções (Material/Prestador) só piora com campo de busca.
  const minimo = props.minimoParaBusca == null ? 6 : props.minimoParaBusca;
  const comBusca = props.semBusca ? false : lista.length >= minimo;

  // Painel em position:fixed, medido a partir do botão: assim ele não é
  // cortado por tabela com overflow nem por card com borda arredondada.
  const medir = useCallback(function () {
    const el = refBotao.current;
    if (!el || typeof window === "undefined") return;
    const r = el.getBoundingClientRect();
    const tetoAltura = 320;
    const abaixo = window.innerHeight - r.bottom - 10;
    const acima = r.top - 10;
    const paraBaixo = abaixo >= 200 || abaixo >= acima;
    const largura = Math.max(r.width, 250);
    setCaixa({
      esquerda: Math.max(8, Math.min(r.left, window.innerWidth - largura - 8)),
      largura: largura,
      topo: paraBaixo ? r.bottom + 4 : null,
      base: paraBaixo ? null : Math.max(8, window.innerHeight - r.top + 4),
      altura: Math.max(150, Math.min(tetoAltura, (paraBaixo ? abaixo : acima))),
    });
  }, []);

  fecharRef.current = fechar;

  useEffect(function () {
    if (props.abrirAoMontar) abrir("");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(function () {
    if (!aberto) return;
    medir();
    function fora(ev) {
      if (refPainel.current && refPainel.current.contains(ev.target)) return;
      if (refBotao.current && refBotao.current.contains(ev.target)) return;
      fecharRef.current();
    }
    document.addEventListener("mousedown", fora, true);
    window.addEventListener("resize", medir);
    window.addEventListener("scroll", medir, true);
    return function () {
      document.removeEventListener("mousedown", fora, true);
      window.removeEventListener("resize", medir);
      window.removeEventListener("scroll", medir, true);
    };
  }, [aberto, medir]);

  // O foco vai para o campo de busca (ou para o painel, quando a lista é
  // curta e não tem busca) — é o que faz as setas e o Enter funcionarem.
  useEffect(function () {
    if (!aberto) return;
    const t = setTimeout(function () {
      if (comBusca && refBusca.current) refBusca.current.focus();
      else if (refPainel.current) refPainel.current.focus();
    }, 0);
    return function () { clearTimeout(t); };
  }, [aberto, comBusca]);

  useEffect(function () {
    if (!aberto || !refPainel.current) return;
    const el = refPainel.current.querySelector('[data-sb-idx="' + marcado + '"]');
    if (el && el.scrollIntoView) el.scrollIntoView({ block: "nearest" });
  }, [aberto, marcado, termo]);

  function abrir(comLetra) {
    jaFocou.current = false;
    setTermo(comLetra || "");
    setMarcado(0);
    setAberto(true);
  }

  // Fechar sem escolher é diferente de escolher: o <select> nativo dispara
  // blur, e há tela que conta com isso para desmontar o campo.
  function fechar() {
    setAberto(false);
    setTermo("");
    if (props.aoFechar) props.aoFechar();
  }

  function escolher(o) {
    setAberto(false);
    setTermo("");
    if (props.onChange) props.onChange(o.valor, o);
  }

  function aoTeclar(e) {
    if (e.key === "Escape") {
      e.preventDefault(); fechar();
      if (refBotao.current) refBotao.current.focus();
      return;
    }
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setMarcado(function (m) { return Math.min(visiveis.length - 1, m + 1); });
      return;
    }
    if (e.key === "ArrowUp") {
      e.preventDefault();
      setMarcado(function (m) { return Math.max(0, m - 1); });
      return;
    }
    if (e.key === "Home") { e.preventDefault(); setMarcado(0); return; }
    if (e.key === "End") { e.preventDefault(); setMarcado(Math.max(0, visiveis.length - 1)); return; }
    if (e.key === "Enter") {
      e.preventDefault();
      const o = visiveis[marcado];
      if (o) escolher(o);
      return;
    }
    if (e.key === "Tab") { fechar(); return; }
    if (!comBusca && e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
      e.preventDefault();
      const agora = Date.now();
      const d = refDigitado.current;
      d.texto = (agora - d.quando < 900 ? d.texto : "") + e.key;
      d.quando = agora;
      const alvo = buscaNormal(d.texto);
      for (let i = 0; i < visiveis.length; i++) {
        if (buscaNormal(visiveis[i].rotulo).indexOf(alvo) === 0) { setMarcado(i); break; }
      }
    }
  }

  const estiloBotao = Object.assign({}, props.style || SB_CAMPO, {
    cursor: props.disabled ? "default" : "pointer",
    textAlign: "left",
    display: "flex",
    alignItems: "center",
    gap: 6,
    opacity: props.disabled ? 0.6 : 1,
    color: escolhida ? "#111827" : "#9ca3af",
  });

  return (
    <>
      <button type="button" ref={refBotao} disabled={!!props.disabled} id={props.id}
        className={props.className}
        /* Diz que isto é um CAMPO, e não um botão de ação: é o que permite à
           regra de toque do celular engordar os campos sem engordar junto o
           "Editar" e o "Excluir" das listas. */
        data-vk-campo="1"
        title={props.title || (escolhida ? escolhida.rotulo : "")}
        style={estiloBotao}
        onClick={function () { if (props.disabled) return; if (aberto) fechar(); else abrir(""); }}
        onKeyDown={function (e) {
          if (props.disabled) return;
          if (aberto) return;
          if (e.key === "ArrowDown" || e.key === "Enter" || e.key === " ") { e.preventDefault(); abrir(""); return; }
          if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) { e.preventDefault(); abrir(e.key); }
        }}>
        <span style={{ flex: 1, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
          {escolhida ? escolhida.rotulo : (props.vazio || "— escolher —")}
        </span>
        <span style={{ color: "#9ca3af", fontSize: 9, flexShrink: 0 }}>▾</span>
      </button>

      {aberto && caixa && (
        <div ref={refPainel} tabIndex={-1} onKeyDown={comBusca ? undefined : aoTeclar}
          style={{
            position: "fixed", zIndex: 4200, left: caixa.esquerda, width: caixa.largura,
            top: caixa.topo != null ? caixa.topo : undefined,
            bottom: caixa.topo != null ? undefined : caixa.base,
            maxHeight: caixa.altura, display: "flex", flexDirection: "column",
            background: "#fff", border: "1px solid rgba(38,36,33,0.16)", borderRadius: 12,
            boxShadow: "0 14px 36px rgba(0,0,0,0.18)", overflow: "hidden", outline: "none",
          }}>
          {comBusca && (
            <div style={{ padding: 8, borderBottom: "1px solid rgba(38,36,33,0.08)", flexShrink: 0 }}>
              <input value={termo} onKeyDown={aoTeclar}
                ref={function (el) {
                  refBusca.current = el;
                  if (el && !jaFocou.current) { jaFocou.current = true; el.focus(); }
                }}
                placeholder={props.placeholder || "Procurar…"}
                onChange={function (e) { setTermo(e.target.value); setMarcado(0); }}
                style={{
                  border: "1px solid #0474f4", borderRadius: 9, padding: "7px 10px", fontSize: 13,
                  width: "100%", boxSizing: "border-box", outline: "none", fontFamily: "inherit",
                }} />
            </div>
          )}
          <div style={{ overflowY: "auto", flex: 1 }}>
            {visiveis.length === 0 && (
              <div style={{ padding: "12px 12px", fontSize: 12.5, color: "#9ca3af" }}>
                nada com esse nome
              </div>
            )}
            {visiveis.map(function (o, i) {
              const cabecalho = o.grupo && (i === 0 || visiveis[i - 1].grupo !== o.grupo);
              const atual = o.valor === valorAtual;
              return (
                <Fragment key={o.valor + "\u0000" + i}>
                  {cabecalho && (
                    <div style={{
                      padding: "7px 12px 3px", fontSize: 10, fontWeight: 700, letterSpacing: 0.5,
                      textTransform: "uppercase", color: "#9ca3af",
                    }}>{o.grupo}</div>
                  )}
                  <div data-sb-idx={i}
                    onMouseEnter={function () { setMarcado(i); }}
                    onMouseDown={function (ev) { ev.preventDefault(); }}
                    onClick={function () { escolher(o); }}
                    style={{
                      padding: "8px 12px", fontSize: 13, cursor: "pointer", lineHeight: 1.3,
                      background: i === marcado ? "#eef5ff" : "transparent",
                      color: i === marcado ? "#0474f4" : "#111827",
                      fontWeight: atual ? 600 : 400,
                    }}>
                    {o.rotulo}
                  </div>
                </Fragment>
              );
            })}
            {filtradas.length > visiveis.length && (
              <div style={{ padding: "8px 12px", fontSize: 11, color: "#9ca3af", borderTop: "1px solid rgba(38,36,33,0.06)" }}>
                mostrando {visiveis.length} de {filtradas.length} — escreva mais para achar o resto
              </div>
            )}
          </div>
          {props.aoCriar && (
            <div onMouseDown={function (ev) { ev.preventDefault(); }}
              onClick={function () { const q = termo; fechar(); props.aoCriar(String(q || "").trim()); }}
              style={{
                padding: "9px 12px", fontSize: 12.5, cursor: "pointer", flexShrink: 0,
                borderTop: "1px solid rgba(38,36,33,0.10)",
                background: visiveis.length === 0 ? "#eef5ff" : "#fff",
                color: "#0474f4", fontWeight: 600,
              }}>
              {rotuloDeCriar(termo, props.criarRotulo)}
            </div>
          )}
        </div>
      )}
    </>
  );
}


// ── Selecao ────────────────────────────────────────────
// Troca direta do <select> nativo: mesmos <option> e <optgroup> dentro, mesmo
// onChange com e.target.value. Serve para varrer o app inteiro sem reescrever
// sessenta handlers — quem precisa montar a lista de fora usa o SelectBusca.

// ── Selecao: parte pura ──────────────────────────────

function textoDeFilhos(n) {
  if (n == null || n === false || n === true) return "";
  if (typeof n === "string") return n;
  if (typeof n === "number") return String(n);
  if (Array.isArray(n)) return n.map(textoDeFilhos).join("");
  if (typeof n === "object" && n.props) return textoDeFilhos(n.props.children);
  return "";
}

function opcoesDosFilhos(filhos) {
  const saida = [];
  function anda(n, grupo) {
    if (n == null || n === false || n === true || n === "") return;
    if (Array.isArray(n)) { n.forEach(function (x) { anda(x, grupo); }); return; }
    if (typeof n !== "object" || !n.props) return;
    if (n.type === "optgroup") { anda(n.props.children, String(n.props.label || "")); return; }
    if (n.type === "option") {
      const rotulo = textoDeFilhos(n.props.children);
      // <option key={e}>{e}</option> sem value vale pelo próprio texto, como no nativo.
      const valor = n.props.value != null ? String(n.props.value) : rotulo;
      saida.push({ valor: valor, rotulo: rotulo || valor, grupo: grupo || "" });
      return;
    }
    if (n.props.children != null) anda(n.props.children, grupo);
  }
  anda(filhos, "");
  return saida;
}

// ── Selecao: fim da parte pura ──────────────────────

function Selecao(props) {
  const opcoes = useMemo(function () { return opcoesDosFilhos(props.children); }, [props.children]);
  const controlado = props.value !== undefined;
  const [interno, setInterno] = useState(props.defaultValue == null ? "" : String(props.defaultValue));
  const escolheu = useRef(false);
  const valor = controlado ? props.value : interno;

  function aoEscolher(v) {
    escolheu.current = true;
    if (!controlado) setInterno(v);
    if (props.onChange) {
      props.onChange({
        target: { value: v }, currentTarget: { value: v },
        stopPropagation: function () {}, preventDefault: function () {},
      });
    }
  }

  return (
    <SelectBusca
      style={props.style} className={props.className} id={props.id} title={props.title}
      value={valor == null ? "" : String(valor)} opcoes={opcoes}
      disabled={props.disabled} vazio={props.vazio} placeholder={props.placeholder}
      minimoParaBusca={props.minimoParaBusca} semBusca={props.semBusca}
      abrirAoMontar={props.autoFocus}
      aoFechar={function () { if (!escolheu.current && props.onBlur) props.onBlur({ target: { value: valor } }); }}
      onChange={aoEscolher} />
  );
}

// ── Menu de ações de uma linha ("⋯") ────────────────────────────
// Numa lista de vinte linhas, três botões em cada uma competem com o que a
// linha tem a dizer — e o botão vermelho de apagar é o que mais puxa o olho,
// sendo o que menos se usa. Fica à vista só o que se faz toda hora; o resto
// se recolhe aqui.
//
// O painel é position:fixed, medido a partir do botão, pela mesma razão do
// SelectBusca: dentro de uma tabela com overflow, um painel absoluto seria
// cortado pela borda do card.
function MenuDeAcoes(props) {
  const itens = (props.itens || []).filter(Boolean);
  // No celular o dedo precisa de alvo: o botao e cada linha do menu passam
  // de 30 para 44px. No desktop o botao continua pequeno, que e o pedido.
  const toque = props.toque != null ? !!props.toque
    : (typeof window !== "undefined" && window.innerWidth < 768);
  const [caixa, setCaixa] = useState(null);
  const refBotao = useRef(null);
  const refPainel = useRef(null);
  const aberto = !!caixa;

  const fechar = useCallback(function () { setCaixa(null); }, []);

  const abrir = useCallback(function () {
    const el = refBotao.current;
    if (!el || typeof window === "undefined") { setCaixa({ top: 0, left: 0 }); return; }
    const r = el.getBoundingClientRect();
    const largura = 164;
    const alturaEstimada = 14 + itens.length * (toque ? 46 : 36);
    const cabeAbaixo = window.innerHeight - r.bottom - 8 >= alturaEstimada;
    // Encosta à direita do botão — é de onde o menu "sai". Quando o botão
    // está perto da margem esquerda (no celular a coluna de ações fica à
    // esquerda), isso jogaria o painel para fora da tela: aí ele encosta à
    // esquerda do botão. Nos dois casos, sem passar das bordas.
    const naDireita = r.right - largura;
    const bruto = naDireita >= 8 ? naDireita : r.left;
    setCaixa({
      left: Math.max(8, Math.min(bruto, window.innerWidth - largura - 8)),
      top: cabeAbaixo ? r.bottom + 6 : Math.max(8, r.top - alturaEstimada - 6),
      largura: largura,
    });
  }, [itens.length, toque]);

  useEffect(function () {
    if (!aberto || typeof document === "undefined") return;
    const foraDaqui = function (e) {
      const p = refPainel.current, b = refBotao.current;
      if (p && p.contains(e.target)) return;
      if (b && b.contains(e.target)) return;
      fechar();
    };
    const naTecla = function (e) { if (e.key === "Escape") fechar(); };
    // Rolar com o menu aberto deixaria o painel parado longe do botão que o
    // abriu — fechar é mais honesto que persegui-lo.
    document.addEventListener("mousedown", foraDaqui, true);
    document.addEventListener("keydown", naTecla, true);
    window.addEventListener("scroll", fechar, true);
    window.addEventListener("resize", fechar);
    return function () {
      document.removeEventListener("mousedown", foraDaqui, true);
      document.removeEventListener("keydown", naTecla, true);
      window.removeEventListener("scroll", fechar, true);
      window.removeEventListener("resize", fechar);
    };
  }, [aberto, fechar]);

  if (!itens.length) return null;

  return (
    <>
      <button ref={refBotao} type="button" aria-haspopup="menu" aria-expanded={aberto ? "true" : "false"}
        title={props.title || "Mais ações"}
        onClick={function (e) { e.stopPropagation(); if (aberto) fechar(); else abrir(); }}
        style={{
          background: aberto ? "rgba(38,36,33,0.06)" : "#fff",
          color: "#4b5563", border: "1.5px solid rgba(38,36,33,0.16)", borderRadius: 10,
          width: toque ? 44 : (props.compacto ? 32 : 36),
          height: toque ? 44 : (props.compacto ? 30 : 34),
          display: "inline-flex", alignItems: "center", justifyContent: "center",
          fontSize: 15, lineHeight: 1, cursor: "pointer", fontFamily: "inherit", padding: 0,
          flexShrink: 0,
        }}>
        <span aria-hidden="true" style={{ marginTop: -3, letterSpacing: 1 }}>···</span>
      </button>
      {aberto && (
        <div ref={refPainel} data-vk-menu-acoes="1" role="menu"
          onClick={function (e) { e.stopPropagation(); }}
          style={{
            position: "fixed", top: caixa.top, left: caixa.left, width: caixa.largura,
            background: "#fff", border: "1px solid rgba(38,36,33,0.14)", borderRadius: 12,
            boxShadow: "0 16px 40px -16px rgba(17,24,39,0.45)", padding: 6, zIndex: 80,
          }}>
          {itens.map(function (it, i) {
            return (
              <button key={i} type="button" role="menuitem" disabled={it.desativado}
                onClick={function () { fechar(); if (it.onClick) it.onClick(); }}
                style={{
                  display: "block", width: "100%", textAlign: "left",
                  background: "none", border: "none", borderRadius: 8,
                  padding: toque ? "13px 10px" : "9px 10px", minHeight: toque ? 44 : "auto",
                  fontSize: toque ? 14 : 13, fontFamily: "inherit",
                  color: it.destrutivo ? "#dc2626" : "#111827",
                  cursor: it.desativado ? "default" : "pointer",
                  opacity: it.desativado ? 0.45 : 1,
                }}
                onMouseEnter={function (e) { if (!it.desativado) e.currentTarget.style.background = "rgba(38,36,33,0.05)"; }}
                onMouseLeave={function (e) { e.currentTarget.style.background = "none"; }}>
                {it.rotulo}
              </button>
            );
          })}
        </div>
      )}
    </>
  );
}


// ════════════════════════════════════════════════════════════
// api.js
// ════════════════════════════════════════════════════════════

// v2 PostgreSQL — Sprint 2
// ═══════════════════════════════════════════════════════════════
// VICKE — API Client
// Centraliza comunicação HTTP com o backend. Todas as chamadas:
// - Enviam Authorization header automático (lê vicke-token do localStorage)
// - Tratam 401 com auto-logout (flag anti-cascata evita N reloads)
// - Retornam data desembrulhado (ou lançam Error em caso de falha)
// ═══════════════════════════════════════════════════════════════

// API_URL vem de shared.jsx (que lê VITE_API_URL ou usa fallback prod).
// Mantemos esta referência local pra não importar shared em cada chamada.
const _API_URL = (typeof import.meta !== "undefined" && import.meta.env && import.meta.env.VITE_API_URL)
  || "https://orbi-production-5f5c.up.railway.app";

// Flag pra evitar múltiplos reloads em cascata quando várias requisições
// retornam 401 ao mesmo tempo (ex: loadAllData faz 8 chamadas em paralelo)
let _sessionExpiredHandled = false;

async function req(method, path, body) {
  const token = typeof localStorage !== "undefined" ? localStorage.getItem("vicke-token") : null;
  const headers = { "Content-Type": "application/json" };
  if (token) headers["Authorization"] = `Bearer ${token}`;

  const res = await fetch(`${_API_URL}${path}`, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
  });

  // Handler global de 401: token expirado/inválido → limpa e volta pra login.
  // Não aplicamos isto a /auth/login (onde 401 significa senha errada).
  if (res.status === 401 && !path.startsWith("/auth/")) {
    if (!_sessionExpiredHandled) {
      _sessionExpiredHandled = true;
      try {
        localStorage.removeItem("vicke-token");
        localStorage.removeItem("vicke-user");
      } catch {}
      if (typeof location !== "undefined") location.reload();
    }
    throw new Error("Sessão expirada — faça login novamente");
  }

  const json = await res.json();
  if (!json.ok) {
    // Anexa status e tipo no Error pra que componentes possam distinguir
    // "sem permissão" (403) de outros erros e mostrar mensagem específica.
    // Ex: PainelEmpresas mostra "você não é master" em vez de erro genérico.
    const erro = new Error(json.error || "Erro na API");
    erro.status = res.status;
    erro.code   = res.status === 403 ? "FORBIDDEN" : "API_ERROR";
    throw erro;
  }
  return json.data;
}

const get  = (path)        => req("GET",    path);
const post = (path, body)  => req("POST",   path, body);
const put  = (path, body)  => req("PUT",    path, body);
const del  = (path)        => req("DELETE", path);

// ── API pública ────────────────────────────────────────────────
const api = {
  clientes: {
    list:   ()       => get("/api/clientes"),
    get:    (id)     => get(`/api/clientes/${id}`),
    save:   (c)      => post("/api/clientes", c),
    update: (id, c)  => put(`/api/clientes/${id}`, c),
    delete: (id)     => del(`/api/clientes/${id}`),
    // Acesso do cliente final à obra dele (login próprio, perfil "cliente").
    acesso: {
      get:      (id)         => get(`/api/clientes/${id}/acesso`),
      criar:    (id, email)  => post(`/api/clientes/${id}/acesso`, { email }),
      ativar:   (id, ativo)  => put(`/api/clientes/${id}/acesso`, { ativo }),
      resetar:  (id)         => put(`/api/clientes/${id}/acesso`, { resetarSenha: true }),
      // entra como o cliente: o servidor devolve um token de visita de 2h
      entrar:   (id)         => post(`/api/clientes/${id}/acesso/entrar`, {}),
    },
  },

  fornecedores: {
    list:   ()       => get("/api/fornecedores"),
    save:   (f)      => post("/api/fornecedores", f),
    update: (id, f)  => put(`/api/fornecedores/${id}`, f),
    delete: (id)     => del(`/api/fornecedores/${id}`),
  },

  materiais: {
    list:   ()       => get("/api/materiais"),
    save:   (m)      => post("/api/materiais", m),
    delete: (id)     => del(`/api/materiais/${id}`),
  },

  obras: {
    list:   ()       => get("/api/obras"),
    save:   (o)      => post("/api/obras", o),
    delete: (id)     => del(`/api/obras/${id}`),
  },

  lancamentos: {
    list:   ()       => get("/api/lancamentos"),
    save:   (l)      => post("/api/lancamentos", l),
    // Importação da planilha do escritório: vai em lotes, não um a um.
    batch:  (lista)  => post("/api/lancamentos/batch", { lancamentos: lista }),
    delete: (id)     => del(`/api/lancamentos/${id}`),
  },

  orcamentos: {
    list:       (clienteId) => get(`/api/orcamentos${clienteId ? `?clienteId=${clienteId}` : ""}`),
    save:       (o)         => post("/api/orcamentos", o),
    update:     (id, o)     => put(`/api/orcamentos/${id}`, o),
    delete:     (id)        => del(`/api/orcamentos/${id}`),
  },

  receitas: {
    list:           (filtros)    => get(`/api/receitas${filtros ? `?${new URLSearchParams(filtros)}` : ""}`),
    save:           (r)          => post("/api/receitas", r),
    batch:          (receitas)   => post("/api/receitas/batch", { receitas }),
    delete:         (id)         => del(`/api/receitas/${id}`),
    deleteByOrc:    (orcId)      => del(`/api/receitas/por-orcamento/${orcId}`),
  },

  // Escritório agora inclui logo no mesmo payload (get/save atômicos).
  // O backend separa internamente: logo vai pra coluna dedicada, resto
  // pro JSONB. Pro frontend, é um objeto só.
  escritorio: {
    get:    ()  => get("/api/escritorio"),
    save:   (e) => put("/api/escritorio", e),
  },

  // Logo continua disponível via endpoint dedicado (compat), mas
  // a rota /api/escritorio também retorna logo junto — preferir ela
  // nos fluxos de boot/carregamento pra evitar request extra.
  logo: {
    get:    ()     => get("/api/logo"),
    save:   (data) => put("/api/logo", { data }),
    clear:  ()     => put("/api/logo", { data: null }),
  },

  // ── UPLOADS (Cloudinary) ────────────────────────────────────
  // Substituirá gradualmente o padrão antigo de base64 no Postgres.
  // 3 categorias: 'logo', 'capa_escritorio', 'imagem_projeto'.
  // Limites por categoria checados no backend; frontend valida tamanho
  // antes pra dar feedback rápido.
  uploads: {
    // Envia File/Blob via multipart. Retorna { url, public_id, width, height, bytes, formato }.
    // Diferente das outras chamadas: NÃO usa req() porque precisa de FormData
    // (multipart) em vez de JSON. Token vai no header como sempre.
    send: async (arquivo, categoria) => {
      const token = typeof localStorage !== "undefined" ? localStorage.getItem("vicke-token") : null;
      const fd = new FormData();
      fd.append("arquivo", arquivo);
      fd.append("categoria", categoria);
      const headers = {};
      if (token) headers["Authorization"] = `Bearer ${token}`;
      // NÃO seta Content-Type — o browser monta o boundary do multipart sozinho.
      const res = await fetch(`${_API_URL}/api/uploads`, {
        method: "POST",
        headers,
        body: fd,
      });
      if (res.status === 401 && !_sessionExpiredHandled) {
        _sessionExpiredHandled = true;
        try { localStorage.removeItem("vicke-token"); localStorage.removeItem("vicke-user"); } catch {}
        if (typeof location !== "undefined") location.reload();
        throw new Error("Sessão expirada — faça login novamente");
      }
      const json = await res.json();
      if (!json.ok) {
        const erro = new Error(json.error || "Erro no upload");
        erro.status = res.status;
        throw erro;
      }
      return json.data;
    },
    // Remove imagem pelo public_id (do Cloudinary + marca inativa no log).
    remove: (public_id) => req("DELETE", "/api/uploads", { public_id }),
    // Lista uploads ativos da empresa (debug/admin). Retorna { uploads, quotas }.
    list:   (categoria) => get(`/api/uploads${categoria ? `?categoria=${encodeURIComponent(categoria)}` : ""}`),
  },

  // ── IA: leitura do orçamento da loja e do pedido do pedreiro ──
  // Só para os escritórios liberados no servidor. Quando falha, o erro traz
  // `motivo` ("token", "limite", "nao_liberada"...) e quem chamou decide cair
  // no leitor por regras.
  //
  // A leitura roda em segundo plano no servidor: o envio responde na hora
  // com o número da leitura, e daqui se pergunta de tempos em tempos como
  // ela está. Assim um orçamento de várias páginas pode levar os minutos que
  // precisar, e uma queda de sinal no meio não perde nada — a próxima
  // pergunta pega de onde parou.
  ia: {
    status: () => get("/api/ia/status"),
    _INTERVALO_MS: 1500,
    _TEMPO_MAX_MS: 6 * 60 * 1000,        // o servidor desiste em 5; aqui, um pouco depois
    _SEM_SINAL_MAX_MS: 90 * 1000,         // quanto tempo sem conseguir perguntar antes de desistir

    _cabecalho: () => {
      const token = typeof localStorage !== "undefined" ? localStorage.getItem("vicke-token") : null;
      return token ? { Authorization: `Bearer ${token}` } : {};
    },

    _erroDe: (res, json, oque) => {
      // Resposta que nem JSON é costuma ser rota que não existe no servidor
      // publicado (404) ou queda (502). Dizer o código evita caçar fantasma.
      const erro = new Error((json && json.error) || `O servidor respondeu erro ${res ? res.status : "?"} na leitura ${oque}.`);
      erro.status = res ? res.status : 0;
      erro.motivo = (json && json.motivo) || "falha";
      return erro;
    },

    // Abre a leitura e acompanha até o fim. aoProgresso recebe
    // { etapa, itens, decorridoMs } a cada pergunta.
    _ler: async (rota, fd, oque, aoProgresso) => {
      fd.append("modo", "fila");
      let res, json = null;
      // Sem resposta nenhuma quase sempre é o servidor reiniciando (cada
      // publicação no Railway derruba o processo por alguns segundos) ou o
      // sinal piscando. Tenta de novo sozinho antes de desistir.
      const esperas = [3000, 6000, 10000];
      const comecouEnvio = Date.now();
      for (let tentativa = 0; ; tentativa++) {
        try {
          res = await fetch(`${_API_URL}${rota}`, { method: "POST", headers: api.ia._cabecalho(), body: fd });
          try { json = await res.json(); } catch (e) { json = null; }
          break;
        } catch (e) {
          if (tentativa >= esperas.length) {
            const erro = new Error("Não consegui falar com o servidor — tentei 4 vezes em 20 segundos. Ele pode estar reiniciando depois de uma publicação; espere um minuto e tente de novo.");
            erro.motivo = "rede"; throw erro;
          }
          if (typeof aoProgresso === "function") aoProgresso({ etapa: "reconectando", itens: null, decorridoMs: Date.now() - comecouEnvio });
          await new Promise((z) => setTimeout(z, esperas[tentativa]));
        }
      }
      if (!json || !json.ok) throw api.ia._erroDe(res, json, oque);
      // servidor antigo, sem fila: a resposta já é o resultado
      if (!json.data || !json.data.leituraId) return json.data;

      const id = json.data.leituraId;
      const comecou = Date.now();
      let semSinalDesde = null;
      for (;;) {
        await new Promise((z) => setTimeout(z, api.ia._INTERVALO_MS));
        if (Date.now() - comecou > api.ia._TEMPO_MAX_MS) {
          const erro = new Error(`A leitura ${oque} passou de ${Math.round(api.ia._TEMPO_MAX_MS / 60000)} minutos.`);
          erro.motivo = "tempo"; throw erro;
        }
        let r = null, j = null;
        try {
          r = await fetch(`${_API_URL}/api/ia/leituras/${encodeURIComponent(id)}`, { headers: api.ia._cabecalho() });
          try { j = await r.json(); } catch (e) { j = null; }
        } catch (e) {
          // sem sinal: continua tentando por um tempo — a leitura segue no servidor
          if (!semSinalDesde) semSinalDesde = Date.now();
          if (Date.now() - semSinalDesde > api.ia._SEM_SINAL_MAX_MS) {
            const erro = new Error("Fiquei sem conexão com o servidor por muito tempo durante a leitura."); erro.motivo = "rede"; throw erro;
          }
          if (typeof aoProgresso === "function") aoProgresso({ etapa: "sem_sinal", itens: null, decorridoMs: Date.now() - comecou });
          continue;
        }
        semSinalDesde = null;
        if (!j || !j.ok) throw api.ia._erroDe(r, j, oque);
        const d = j.data || {};
        if (typeof aoProgresso === "function") aoProgresso({ etapa: d.etapa, itens: d.itens, decorridoMs: d.decorridoMs });
        if (d.estado === "pronto") return d.resultado;
        if (d.estado === "erro") {
          const erro = new Error(d.erro || `A IA não conseguiu fazer a leitura ${oque}.`); erro.motivo = d.motivo || "falha"; throw erro;
        }
      }
    },

    // O pedido pode vir como texto colado, como arquivo, ou os dois.
    lerPedido: async ({ arquivo, texto }, aoProgresso) => {
      const fd = new FormData();
      if (arquivo) fd.append("arquivo", arquivo);
      fd.append("texto", texto || "");
      return api.ia._ler("/api/ia/ler-pedido", fd, "do pedido", aoProgresso);
    },

    // Qualquer papel de despesa: nota, comprovante, cupom, recibo, foto.
    // Volta { documentos: [...] } — um por papel achado no arquivo.
    lerDocumento: async (arquivo, aoProgresso, texto) => {
      const fd = new FormData();
      if (arquivo) fd.append("arquivo", arquivo);
      if (texto) fd.append("texto", texto);
      return api.ia._ler("/api/ia/ler-documento", fd, "do papel", aoProgresso);
    },

    lerOrcamento: async (arquivo, itens, aoProgresso) => {
      const fd = new FormData();
      fd.append("arquivo", arquivo);
      fd.append("itens", JSON.stringify(itens || []));
      return api.ia._ler("/api/ia/ler-orcamento", fd, "do orçamento", aoProgresso);
    },
  },

  config: {
    get:  (chave)        => get(`/api/config/${chave}`),
    save: (chave, dados) => put(`/api/config/${chave}`, dados),
  },

  // ── ADMIN (só master) ──────────────────────────────────────
  admin: {
    empresas: {
      list:   ()           => get("/admin/empresas"),
      get:    (id)         => get(`/admin/empresas/${id}`),
      save:   (e)          => post("/admin/empresas", e),
      update: (id, e)      => put(`/admin/empresas/${id}`, e),
      delete: (id)         => del(`/admin/empresas/${id}`),
    },
    usuarios: {
      list:       ()           => get("/admin/usuarios"),
      save:       (u)          => post("/admin/usuarios", u),
      update:     (id, u)      => put(`/admin/usuarios/${id}`, u),
      delete:     (id)         => del(`/admin/usuarios/${id}`),
      // Reset administrativo: gera senha aleatória, retorna em texto puro.
      // Master pode resetar qualquer usuário (qualquer empresa). Backend
      // bloqueia self-reset (use /auth/trocar-senha pra trocar a própria).
      resetSenha: (id)         => post(`/admin/usuarios/${id}/reset-senha`),
    },
    mensagens: {
      // Caixa de email do Master (Sprint 3 Bloco E).
      // ?filtro=nao-lidas filtra só não lidas; sem param retorna todas.
      list:        (filtro) => get(`/admin/mensagens${filtro ? `?filtro=${filtro}` : ""}`),
      get:         (id)     => get(`/admin/mensagens/${id}`),
      marcarLida:  (id)     => put(`/admin/mensagens/${id}/lida`, {}),
      marcarNaoLida:(id)    => put(`/admin/mensagens/${id}/nao-lida`, {}),
      delete:      (id)     => del(`/admin/mensagens/${id}`),
      responder:   (id, dados) => post(`/admin/mensagens/${id}/responder`, dados),
    },
    manutencao: ()         => post("/admin/manutencao"),
    dashboard:  ()         => get("/admin/dashboard"),

    // Caixa de feedback in-app — listagem master com filtros, controle de status.
    // Diferente de admin.mensagens (que é caixa de email externo via Resend webhook).
    feedback: {
      list: (filtros = {}) => {
        const qs = new URLSearchParams();
        if (filtros.categoria) qs.set("categoria", filtros.categoria);
        if (filtros.status)    qs.set("status", filtros.status);
        if (filtros.busca)     qs.set("busca", filtros.busca);
        const s = qs.toString();
        return get(`/admin/feedback${s ? "?" + s : ""}`);
      },
      get:    (id)        => get(`/admin/feedback/${id}`),
      update: (id, dados) => put(`/admin/feedback/${id}`, dados),
      delete: (id)        => del(`/admin/feedback/${id}`),
    },

    // CUB — Custo Unitário Básico (Sprint 1)
    cub: {
      list:      ()           => get("/api/cub"),                    // todos os valores
      listEstado:(uf)         => get(`/api/cub/${uf}`),              // valores de um estado
      // Valor atual (mais recente) pra uma combinação estado/categoria/padrão.
      // Usado no onboarding (mostra exemplo de cálculo) e no orçamento (Sprint 3).
      // Padrão default = "Normal" (NBR 12721); UI pode mostrar como "Médio".
      atual:     (estado, categoria = "R-1", padrao = "Normal") =>
                   get(`/api/cub/atual?estado=${encodeURIComponent(estado)}&categoria=${encodeURIComponent(categoria)}&padrao=${encodeURIComponent(padrao)}`),
      atualizar: (estados)    => post("/admin/cub/atualizar", estados ? { estados } : {}),
      log:       (limit = 50) => get(`/admin/cub/log?limit=${limit}`),
      status:    ()           => get("/admin/cub/status"),
    },

    // SINAPI — produtividade (HH), preço da hora e insumos, coletados no backend
    sinapi: {
      parametros: ()        => get("/api/sinapi/parametros"),
      atualizar:  (forcar)  => post("/admin/sinapi/atualizar", { forcar: !!forcar }),
      status:     ()        => get("/admin/sinapi/status"),
    },
  },

  // ── ONBOARDING (Sprint 3 — modelo pricing baseado em CUB) ──
  // Tela bloqueante pra empresas novas: 6 perguntas + estado + calibragem.
  // Resultado: pct_matriz_calculado / pct_calibrado salvos na empresa.
  onboarding: {
    // Retorna a matriz de ratings (faixas + labels) pra renderizar opções.
    matriz:   ()       => get("/api/onboarding/matriz"),
    // Body: { profissao, porte, experiencia, referencia, padrao_projetos,
    //         capital, estado, valor_calibrado? }
    concluir: (dados)  => post("/api/onboarding/concluir", dados),
  },

  // ── DEV MODE (rotas de reset gated por escritorio.dev_mode no backend) ──
  // Disponível só pra empresas em modo dev (Vicke Dev). UI esconde os
  // botões pra outras empresas; backend re-checa.
  dev: {
    resetOrcamentos:         () => post("/api/dev/reset/orcamentos", {}),
    resetOnboardingEmpresa:  () => post("/api/dev/reset/onboarding-empresa", {}),
    resetOnboardingOrcamento:() => post("/api/dev/reset/onboarding-orcamento", {}),
    resetTudo:               () => post("/api/dev/reset/tudo", {}),
  },

  // ── CUB top-level (atalho pra usar fora do contexto admin) ──
  // Permite api.cub.atual(...) sem ter que digitar api.admin.cub.atual.
  // Usado pelo onboarding e pelo orçamento (Sprint 3).
  cub: {
    atual: (estado, categoria = "R-1", padrao = "Normal") =>
             get(`/api/cub/atual?estado=${encodeURIComponent(estado)}&categoria=${encodeURIComponent(categoria)}&padrao=${encodeURIComponent(padrao)}`),
  },

  // ── EMPRESA/USUÁRIOS (admin do escritório) ─────────────────
  empresa: {
    usuarios: {
      list:       ()           => get("/empresa/usuarios"),
      save:       (u)          => post("/empresa/usuarios", u),
      update:     (id, u)      => put(`/empresa/usuarios/${id}`, u),
      delete:     (id)         => del(`/empresa/usuarios/${id}`),
      // Admin de empresa só reseta colegas da própria empresa (backend valida).
      // Não pode resetar usuário master nem a si mesmo.
      resetSenha: (id)         => post(`/empresa/usuarios/${id}/reset-senha`),
    },
  },

  // ── AUTH (qualquer usuário autenticado) ────────────────────
  auth: {
    me:           ()                          => get("/auth/me"),
    // Troca da própria senha. Exige senha atual pra prevenir abuso de
    // sessão sequestrada. Zera precisa_trocar_senha se a flag estiver setada.
    trocarSenha:  (senha_atual, senha_nova)   => post("/auth/trocar-senha", { senha_atual, senha_nova }),
    // Recuperação de senha self-service (público — sem token JWT).
    // recuperar: usuário pede via email; backend manda link com token único.
    // redefinir: usuário usa o token do link pra setar senha nova.
    recuperar:    (email)                     => post("/auth/recuperar-senha", { email }),
    redefinir:    (token, senha_nova)         => post("/auth/redefinir-senha", { token, senha_nova }),
  },

  // ── FEEDBACK IN-APP (qualquer usuário autenticado) ─────────
  // Botão flutuante no app dispara aqui. Backend grava em feedback_app
  // com snapshot de quem enviou + empresa.
  feedback: {
    enviar: (categoria, texto) => post("/feedback", { categoria, texto }),
  },

  backup: {
    exportar: () => get("/api/backup"),
    importar: (dados) => post("/api/backup/importar", dados),
  },

  health: () => get("/api/health"),
};

// ── Carrega todos os dados de uma vez ──────────────────────────
// Substitui o DB.get("obramanager-v1") do sistema antigo.
// Escritório agora vem com logo embutido (um só request).
// Sprint 3: também carrega CUB (Baixo/Normal/Alto) do estado da empresa
// em paralelo, pra ficar disponível no orçamento desde o boot.
// Se estado for null (empresa sem onboarding), pula a busca do CUB
// — orçamento usa fallback R$ 45 fixo nesse caso.
// O acesso do cliente final só enxerga uma lista curta de caminhos no backend
// (clientes, obras, fornecedores, escritório, orçamentos, CUB). Pedir
// /materiais, /lancamentos ou /receitas devolve 403 e derrubava o
// carregamento inteiro — o app caía no SEED e o cliente via "Acesso sem obra
// vinculada". Para ele, essas listas vêm vazias; o painel da obra não usa
// nenhuma delas.
function ehAcessoDeCliente() {
  try {
    const u = JSON.parse(localStorage.getItem("vicke-user") || "null");
    return u?.perfil === "cliente";
  } catch { return false; }
}

async function loadAllData(estado = null) {
  const cliente = ehAcessoDeCliente();
  const soEscritorio = (fn) => (cliente ? Promise.resolve([]) : fn());
  // Promises base (sempre carregadas)
  const promisesBase = [
    api.clientes.list(),
    api.fornecedores.list(),
    soEscritorio(() => api.materiais.list()),
    api.obras.list(),
    soEscritorio(() => api.lancamentos.list()),
    api.orcamentos.list(),
    soEscritorio(() => api.receitas.list()),
    api.escritorio.get(),
    // Parâmetros SINAPI (globais; null enquanto o backend não coletou)
    api.admin.sinapi.parametros().catch(() => null),
  ];

  // Promises do CUB (só se estado disponível).
  // Carrega categorias específicas por tipo de projeto:
  // - R-1 para Residencial/Clínica (padrões: Baixo, Normal, Alto)
  // - CSL-8 para Conj. Comercial (padrões: Normal, Alto + fallback Baixo→Normal)
  // - PP-4 para Apartamento (Prédio Popular; padrões: Baixo, Normal)
  // - GI para Galpão (padrão único)
  const cubPromises = estado ? [
    // R-1 (Residencial/Clínica)
    api.cub.atual(estado, "R-1", "Baixo").catch(() => null),
    api.cub.atual(estado, "R-1", "Normal").catch(() => null),
    api.cub.atual(estado, "R-1", "Alto").catch(() => null),
    // CSL-8 (Conj. Comercial)
    api.cub.atual(estado, "CSL-8", "Normal").catch(() => null),
    api.cub.atual(estado, "CSL-8", "Alto").catch(() => null),
    // PP-4 (Apartamento — Prédio Popular, até 4 pavimentos)
    api.cub.atual(estado, "PP-4", "Baixo").catch(() => null),
    api.cub.atual(estado, "PP-4", "Normal").catch(() => null),
    // R-8 (Residencial multifamiliar acima de 4 pavimentos)
    api.cub.atual(estado, "R-8", "Baixo").catch(() => null),
    api.cub.atual(estado, "R-8", "Normal").catch(() => null),
    api.cub.atual(estado, "R-8", "Alto").catch(() => null),
    // GI (Galpão)
    api.cub.atual(estado, "GI", "Único").catch(() => null),
  ] : Array(8).fill(Promise.resolve(null));

  const [
    clientes,
    fornecedores,
    materiais,
    obras,
    lancamentos,
    orcamentosProjeto,
    receitasFinanceiro,
    escritorio,
    sinapi,
    r1Baixo, r1Normal, r1Alto,
    csl8Normal, csl8Alto,
    pp4Baixo, pp4Normal,
    r8Baixo, r8Normal, r8Alto,
    giUnico,
  ] = await Promise.all([...promisesBase, ...cubPromises]);

  // DEBUG: mostra valores brutos antes de processar


  // Monta objeto cub estruturado por categoria.
  // Cada categoria pode ter padrões nulos se a API falhar.
  // getPrecoBaseDinamico já lida com isso retornando fallback fixo.
  let cub = null;
  if (estado && (r1Baixo || r1Normal || r1Alto || csl8Normal || csl8Alto || pp4Baixo || pp4Normal
      || r8Baixo || r8Normal || r8Alto || giUnico)) {
    cub = {
      estado,
      R1: {
        Baixo: r1Baixo?.data || r1Baixo,
        Normal: r1Normal?.data || r1Normal,
        Alto: r1Alto?.data || r1Alto,
      },
      CSL8: {
        Normal: csl8Normal?.data || csl8Normal,
        Alto: csl8Alto?.data || csl8Alto,
      },
      PP4: {
        Baixo: pp4Baixo?.data || pp4Baixo,
        Normal: pp4Normal?.data || pp4Normal,
      },
      R8: {
        Baixo: r8Baixo?.data || r8Baixo,
        Normal: r8Normal?.data || r8Normal,
        Alto: r8Alto?.data || r8Alto,
      },
      GI: {
        Unico: giUnico?.data || giUnico,
      },
    };
  }

  return {
    clientes,
    fornecedores,
    materiais,
    obras,
    lancamentos,
    orcamentosProjeto,
    receitasFinanceiro,
    // escritorio já vem com { ...dados, logo } do backend
    escritorio: escritorio || {},
    cub,
    sinapi: sinapi || null,
  };
}

// ── Salva diffs entre newData e oldData ────────────────────────
// Calcula o que mudou e só envia os itens modificados pro backend.
// Cada módulo é independente — erro em um não afeta os outros.
// Quem mudou e quem sumiu, em uma passada por lista.
// A comparação ingênua (um find dentro de um filter) custa n² — com os
// milhares de lançamentos do histórico do escritório, marcar UM lançamento
// como conferido varria a lista inteira para cada item e travava a tela.
// Com um índice por id, é uma passada só.
function _mudadosERemovidos(novos, velhos) {
  const antes = new Map((velhos || []).map(v => [v && v.id, v]));
  const agora = new Map((novos || []).map(n => [n && n.id, n]));
  const mudados = (novos || []).filter(n => {
    const v = antes.get(n && n.id);
    return !v || JSON.stringify(v) !== JSON.stringify(n);
  });
  const removidos = (velhos || []).filter(v => !agora.has(v && v.id));
  return { mudados, removidos };
}

async function saveAllData(newData, oldData = {}) {
  const tasks = [];

  // Clientes
  const clientesNovos = (newData.clientes || []).filter(
    c => !oldData.clientes?.find(o => o.id === c.id && JSON.stringify(o) === JSON.stringify(c))
  );
  const clientesRemovidos = (oldData.clientes || []).filter(
    o => !newData.clientes?.find(c => c.id === o.id)
  );
  clientesNovos.forEach(c => tasks.push(api.clientes.save(c)));
  clientesRemovidos.forEach(c => tasks.push(api.clientes.delete(c.id)));

  // Fornecedores
  const fornsNovos = (newData.fornecedores || []).filter(
    f => !oldData.fornecedores?.find(o => o.id === f.id && JSON.stringify(o) === JSON.stringify(f))
  );
  const fornsRemovidos = (oldData.fornecedores || []).filter(
    o => !newData.fornecedores?.find(f => f.id === o.id)
  );
  fornsNovos.forEach(f => tasks.push(api.fornecedores.save(f)));
  fornsRemovidos.forEach(f => tasks.push(api.fornecedores.delete(f.id)));

  // Orçamentos
  const orcsNovos = (newData.orcamentosProjeto || []).filter(
    o => !oldData.orcamentosProjeto?.find(a => a.id === o.id && JSON.stringify(a) === JSON.stringify(o))
  );
  const orcsRemovidos = (oldData.orcamentosProjeto || []).filter(
    a => !newData.orcamentosProjeto?.find(o => o.id === a.id)
  );
  orcsNovos.forEach(o => tasks.push(api.orcamentos.save(o)));
  orcsRemovidos.forEach(o => tasks.push(api.orcamentos.delete(o.id)));

  // Receitas
  const recNovos = (newData.receitasFinanceiro || []).filter(
    r => !oldData.receitasFinanceiro?.find(a => a.id === r.id && JSON.stringify(a) === JSON.stringify(r))
  );
  const recRemovidos = (oldData.receitasFinanceiro || []).filter(
    a => !newData.receitasFinanceiro?.find(r => r.id === a.id)
  );
  recNovos.forEach(r => tasks.push(api.receitas.save(r)));
  recRemovidos.forEach(r => tasks.push(api.receitas.delete(r.id)));

  // Obras
  const obrasNovas = (newData.obras || []).filter(
    o => !oldData.obras?.find(a => a.id === o.id && JSON.stringify(a) === JSON.stringify(o))
  );
  const obrasRemovidas = (oldData.obras || []).filter(
    a => !newData.obras?.find(o => o.id === a.id)
  );
  obrasNovas.forEach(o => tasks.push(api.obras.save(o)));
  obrasRemovidas.forEach(o => tasks.push(api.obras.delete(o.id)));

  // Lançamentos
  const { mudados: lancsNovos, removidos: lancsRemovidos } =
    _mudadosERemovidos(newData.lancamentos, oldData.lancamentos);
  lancsNovos.forEach(l => tasks.push(api.lancamentos.save(l)));
  lancsRemovidos.forEach(l => tasks.push(api.lancamentos.delete(l.id)));

  // Materiais / Insumos — faltava aqui: o catálogo semeado ou editado em
  // Insumos ficava só em memória e sumia no reload.
  const { mudados: matsNovos, removidos: matsRemovidos } =
    _mudadosERemovidos(newData.materiais, oldData.materiais);
  matsNovos.forEach(m => tasks.push(api.materiais.save(m)));
  matsRemovidos.forEach(m => tasks.push(api.materiais.delete(m.id)));

  // Escritório (inclui logo agregado no mesmo objeto)
  if (newData.escritorio && JSON.stringify(newData.escritorio) !== JSON.stringify(oldData.escritorio)) {
    tasks.push(api.escritorio.save(newData.escritorio));
  }

  await Promise.all(tasks);
}

