// outros.jsx
// ════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════
// MÓDULO ETAPAS (Kanban de Projetos)
// ═══════════════════════════════════════════════════════════════
// Kanban com 6 colunas fixas:
//   Briefing → Estudo Preliminar → Aprovação Cliente → Prefeitura → Executivo → Engenharia
//
// Colunas de ESPERA (dependem de terceiros): Briefing, Aprovação Cliente, Prefeitura
//   → visual com borda pontilhada + fundo levemente bege
// Colunas de TRABALHO (escritório): Estudo Preliminar, Executivo, Engenharia
//   → visual padrão
//
// Card: cliente · referência · tipo · área · valor · executor · revisor · prazo
// Projeto nasce automaticamente quando orçamento é marcado como "Ganho"
// ═══════════════════════════════════════════════════════════════

const ETAPAS_COLS = [
  { key:"briefing",     label:"Briefing",           wait:true  },
  { key:"preliminar",   label:"Estudo Preliminar",  wait:false },
  { key:"prefeitura",   label:"Prefeitura",         wait:true  },
  { key:"executivo",    label:"Executivo",          wait:false },
  { key:"engenharia",   label:"Engenharia",         wait:false },
];

const TIPO_TAGS = {
  "Residencial":     { label:"Residencial",     bg:"#eff6ff", color:"#2563eb" },
  "Clínica":         { label:"Clínica",         bg:"#f0fdf4", color:"#16a34a" },
  "Conj. Comercial": { label:"Conj. Comercial", bg:"#fef3c7", color:"#b45309" },
  "Galpão":          { label:"Galpão",          bg:"#f3e8ff", color:"#7c3aed" },
  "Empreendimento":  { label:"Empreendimento",  bg:"#fef3c7", color:"#b45309" },
};

// Funções utilitárias
function fmtDataBR(d) {
  if (!d) return "";
  const date = new Date(d);
  if (isNaN(date.getTime())) return "";
  return date.toLocaleDateString("pt-BR", { day:"2-digit", month:"short" }).replace(".", "");
}
function diasRestantes(dtAlvo) {
  if (!dtAlvo) return null;
  const alvo = new Date(dtAlvo);
  const hoje = new Date(); hoje.setHours(0,0,0,0);
  const diff = Math.ceil((alvo - hoje) / (1000*60*60*24));
  return diff;
}
function brlCurto(v) {
  if (v == null || v === 0) return "—";
  if (v >= 1000000) return (v/1000000).toLocaleString("pt-BR",{minimumFractionDigits:1,maximumFractionDigits:1}) + "M";
  if (v >= 1000) return Math.round(v/1000) + "k";
  return Math.round(v).toString();
}

function Etapas({ data, save }) {
  // IMPORTANTE: hooks DEVEM ser chamados antes de qualquer return condicional
  // (regra do React: ordem dos hooks deve ser constante entre renders)
  const [filtro, setFiltro] = useState("todos"); // "todos" | "meus" | "atrasados"
  const [busca, setBusca] = useState("");

  // Defensive: guard pra quando data ainda não carregou
  if (!data) {
    return (
      <div style={{ padding:"24px 28px" }}>
        <h2 style={{ color:"#111827", fontWeight:700, fontSize:22, margin:0, letterSpacing:-0.5 }}>Etapas</h2>
        <div style={{ color:"#4b5563", fontSize:13, marginTop:4 }}>Carregando…</div>
      </div>
    );
  }

  const projetos = data.projetos || [];
  const clientes = data.clientes || [];

  // Filtra projetos conforme filtro + busca
  const projetosFiltrados = projetos.filter(p => {
    if (filtro === "atrasados") {
      const dias = diasRestantes(p.prazoEtapa);
      if (dias == null || dias >= 0) return false;
    }
    if (busca) {
      const cli = clientes.find(c => c.id === p.clienteId);
      const nomeCli = cli?.nome || "";
      const ref = p.referencia || "";
      const q = busca.toLowerCase();
      if (!nomeCli.toLowerCase().includes(q) && !ref.toLowerCase().includes(q)) return false;
    }
    return true;
  });

  const qtdAtrasados = projetos.filter(p => {
    const d = diasRestantes(p.prazoEtapa);
    return d != null && d < 0;
  }).length;

  function projetosDaColuna(colKey) {
    return projetosFiltrados.filter(p => (p.colunaEtapa || "briefing") === colKey);
  }

  // Finaliza projeto → move pra Obras
  async function finalizarProjeto(projeto) {
    const nomeCli = clientes.find(c=>c.id===projeto.clienteId)?.nome || "—";
    const ok = await dialogo.confirmar({
      titulo: `Finalizar projeto de ${nomeCli}?`,
      mensagem: `O projeto sairá do Kanban Etapas e será enviado para o módulo Obras como "Em andamento".`,
      confirmar: "Finalizar",
    });
    if (!ok) return;
    const agora = new Date().toISOString();
    const novaObra = {
      id: "OBR-" + Date.now(),
      projetoId: projeto.id,
      orcId: projeto.orcId || null,
      clienteId: projeto.clienteId,
      tipo: projeto.tipo,
      subtipo: projeto.subtipo,
      padrao: projeto.padrao,
      tamanho: projeto.tamanho,
      referencia: projeto.referencia || "",
      areaTotal: projeto.areaTotal || projeto.area || 0,
      status: "em_andamento",
      iniciadaEm: agora,
    };
    const novosProjetos = projetos.filter(p => p.id !== projeto.id);
    const novasObras = [...(data.obras || []), novaObra];
    save({ ...data, projetos: novosProjetos, obras: novasObras }).catch(console.error);
  }

  return (
    <div style={{ padding:"24px 28px", display:"flex", flexDirection:"column", height:"100%", overflow:"hidden" }}>
      {/* Cabeçalho */}
      <div style={{ marginBottom:16 }}>
        <h2 style={{ color:"#111827", fontWeight:700, fontSize:22, margin:0, letterSpacing:-0.5 }}>Etapas</h2>
        <div style={{ color:"#4b5563", fontSize:13, marginTop:4 }}>Acompanhamento dos projetos em andamento</div>
      </div>

      {/* Toolbar: filtros + busca */}
      <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:16, flexWrap:"wrap" }}>
        <FilterPill label="Todos" count={projetos.length} active={filtro==="todos"} onClick={()=>setFiltro("todos")} />
        <FilterPill label="Atrasados" count={qtdAtrasados} active={filtro==="atrasados"} onClick={()=>setFiltro("atrasados")} countColor="#dc2626" />
        <input
          value={busca}
          onChange={e => setBusca(e.target.value)}
          placeholder="Buscar cliente ou referência…"
          style={{
            flex:1, maxWidth:240, padding:"6px 12px",
            border:"1.5px solid rgba(38,36,33,0.16)", borderRadius:6,
            fontSize:12.5, color:"#111827", background:"#fff",
            fontFamily:"inherit", outline:"none",
          }}
        />
      </div>

      {/* Kanban */}
      <div style={{ flex:1, display:"flex", gap:12, overflowX:"auto", overflowY:"hidden", paddingBottom:8 }}>
        {ETAPAS_COLS.map(col => {
          const cards = projetosDaColuna(col.key);
          return (
            <KanbanColumn key={col.key} col={col} cards={cards} clientes={clientes} />
          );
        })}
      </div>

      {/* Estado vazio global */}
      {projetos.length === 0 && (
        <div style={{
          position:"absolute", top:"50%", left:"50%", transform:"translate(-50%, -50%)",
          textAlign:"center", color:"#4b5563", fontSize:13, pointerEvents:"none",
        }}>
          <div style={{ fontSize:14, color:"#4b5563", marginBottom:4 }}>Nenhum projeto em andamento</div>
          <div>Projetos são criados automaticamente quando um orçamento é marcado como <strong>Ganho</strong>.</div>
        </div>
      )}
    </div>
  );
}

// ─── Filter pill (botão de filtro) ──────────────────────────
function FilterPill({ label, count, active, onClick, countColor }) {
  return (
    <button
      onClick={onClick}
      style={{
        fontSize:12, color: active ? "#0474f4" : "#4b5563",
        border:"1.5px solid " + (active ? "#0474f4" : "rgba(38,36,33,0.16)"),
        borderRadius:20, padding:"5px 12px",
        background: "#fff",
        cursor:"pointer", fontFamily:"inherit",
        display:"flex", alignItems:"center", gap:5,
      }}>
      {label}
      {count != null && count > 0 && (
        <strong style={{ marginLeft:4, color: countColor || "#262421" }}>{count}</strong>
      )}
    </button>
  );
}

// ─── Coluna do Kanban ──────────────────────────────────────
function KanbanColumn({ col, cards, clientes }) {
  const wait = col.wait;
  return (
    <div style={{
      flex:"0 0 280px", display:"flex", flexDirection:"column",
      background: wait ? "#fbfaf6" : "#fafafa",
      border: wait ? "1px dashed #e5e7eb" : "1px solid #f0f0f0",
      borderRadius: 14, maxHeight:"100%",
    }}>
      <div style={{
        padding:"14px 14px 10px",
        display:"flex", alignItems:"center", justifyContent:"space-between",
        borderBottom: wait ? "1px dashed #e5e7eb" : "1px solid #f3f4f6",
      }}>
        <span style={{
          fontSize:11, fontWeight:600, color:"#111827",
          textTransform:"uppercase", letterSpacing:0.8,
        }}>{col.label}</span>
        <span style={{
          background: wait ? "#f3efe0" : "#f3f4f6",
          color: wait ? "#a88a3f" : "#9ca3af",
          fontSize:10, fontWeight:600, padding:"2px 7px", borderRadius: 14,
          minWidth:20, textAlign:"center",
        }}>{cards.length}</span>
      </div>
      <div style={{ flex:1, padding:10, display:"flex", flexDirection:"column", gap:8, overflowY:"auto" }}>
        {cards.length === 0 ? (
          <div style={{ fontSize:11, color:"#4b5563", textAlign:"center", padding:"20px 0", fontStyle:"italic" }}>
            Nenhum projeto
          </div>
        ) : cards.map(card => (
          <ProjetoCard key={card.id} projeto={card} clientes={clientes} col={col} onFinalizar={finalizarProjeto} />
        ))}
      </div>
    </div>
  );
}

// ─── Card de projeto ───────────────────────────────────────
function ProjetoCard({ projeto, clientes, col, onFinalizar }) {
  const cliente = clientes.find(c => c.id === projeto.clienteId);
  const nomeCli = cliente?.nome || projeto.clienteNome || "—";
  const ref = projeto.referencia || "";
  const tipo = projeto.tipo || "Residencial";
  const tag = TIPO_TAGS[tipo] || TIPO_TAGS["Residencial"];
  const area = projeto.area || projeto.areaTotal || 0;
  const valor = projeto.valor || 0;

  const dias = diasRestantes(projeto.prazoEtapa);
  const atrasado = dias != null && dias < 0;
  const isEngenharia = col.key === "engenharia";

  return (
    <div style={{
      background:"#fff",
      border: atrasado ? "1px solid #fecaca" : "1px solid rgba(38,36,33,0.14)",
      borderRadius: 12, padding:12,
      cursor:"pointer", transition:"all 0.15s",
      display:"flex", flexDirection:"column", gap:8,
      ...(atrasado ? { background:"#fffbfb" } : {}),
    }}
    onMouseEnter={e => { e.currentTarget.style.borderColor = atrasado ? "#fca5a5" : "#0474f4"; }}
    onMouseLeave={e => { e.currentTarget.style.borderColor = atrasado ? "#fecaca" : "rgba(38,36,33,0.14)"; }}>
      {/* Tag de tipo */}
      <span style={{
        display:"inline-flex", alignItems:"center",
        fontSize:9.5, fontWeight:600, textTransform:"uppercase", letterSpacing:0.6,
        padding:"2px 7px", borderRadius:4,
        width:"fit-content",
        background: tag.bg, color: tag.color,
      }}>{tag.label}</span>

      {/* Nome cliente */}
      <div style={{ fontSize:13.5, fontWeight:600, color:"#111827", lineHeight:1.3 }}>{nomeCli}</div>
      {ref && (
        <div style={{ fontSize:11.5, color:"#4b5563", lineHeight:1.3 }}>{ref}</div>
      )}

      {/* Meta: área + valor */}
      {(area > 0 || valor > 0) && (
        <div style={{ display:"flex", gap:10, fontSize:11, color:"#4b5563", marginTop:2 }}>
          {area > 0 && <span><strong style={{ color:"#111827", fontWeight:600 }}>{area}</strong> m²</span>}
          {valor > 0 && <span>R$ <strong style={{ color:"#111827", fontWeight:600 }}>{brlCurto(valor)}</strong></span>}
        </div>
      )}

      {/* Footer: responsável(is) + prazo */}
      <CardFooter projeto={projeto} col={col} dias={dias} atrasado={atrasado} />

      {/* Botão Finalizar (só na coluna Engenharia) */}
      {isEngenharia && onFinalizar && (
        <button
          onClick={(e) => { e.stopPropagation(); onFinalizar(projeto); }}
          style={{
            marginTop:6, background:"#16a34a", color:"#fff",
            border:"none", borderRadius:6, padding:"6px 10px",
            fontSize:11, fontWeight:600, cursor:"pointer", fontFamily:"inherit",
          }}>
          ✓ Finalizar projeto → Obras
        </button>
      )}
    </div>
  );
}

// ─── Footer do card (responsável + prazo) ──────────────────
function CardFooter({ projeto, col, dias, atrasado }) {
  // Estado transversal "aguardando aprovação do cliente" se sobrepõe ao layout normal
  const aguardandoAprovacao = projeto.aprovacaoStatus === "pendente";

  if (col.wait || aguardandoAprovacao) {
    // Layout de espera: motivo do bloqueio + responsável do escritório
    let motivo;
    if (aguardandoAprovacao) {
      motivo = "Aguardando aprovação do cliente";
    } else {
      motivo = projeto.motivoBloqueio || motivoPadrao(col.key);
    }
    return (
      <div style={{ paddingTop:8, borderTop:"1px solid #f3f4f6", marginTop:2, display:"flex", flexDirection:"column", gap:4 }}>
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:8 }}>
          <div style={{
            fontSize:11.5, fontWeight:600, lineHeight:1.3,
            color: atrasado ? "#991b1b" : "#92400e",
          }}>{motivo}</div>
          <span style={{
            fontSize:11, whiteSpace:"nowrap",
            color: atrasado ? "#dc2626" : (dias != null && dias <= 3 ? "#d97706" : "#6b7280"),
            fontWeight: (atrasado || (dias != null && dias <= 3)) ? 600 : 400,
          }}>
            {dias == null ? "" : atrasado ? `atrasado ${Math.abs(dias)} dias` : dias === 0 ? "vence hoje" : `faltam ${dias} dias`}
          </span>
        </div>
        {projeto.responsavelAcompanha && (
          <div style={{ fontSize:11.5, color:"#111827", lineHeight:1.3 }}>
            <strong style={{ fontWeight:600, color:"#111827" }}>{projeto.responsavelAcompanha}</strong>
            <span style={{ color:"#4b5563", fontWeight:400 }}> — Acompanhamento</span>
          </div>
        )}
      </div>
    );
  }

  // Colunas de trabalho: executor + revisor
  const executor = projeto.executor || "—";
  const revisor = projeto.revisor || "—";
  const mesmapessoa = executor === revisor;
  const estado = projeto.estadoTrabalho || "execucao"; // "execucao" | "revisao" | "ajustes"

  return (
    <div style={{ paddingTop:8, borderTop:"1px solid #f3f4f6", marginTop:2 }}>
      {mesmapessoa ? (
        // Executor = Revisor → linha única
        <PessoaRow
          icon={estado === "revisao" ? "🔍" : "✏️"}
          nome={executor}
          funcao={estado === "revisao" ? "Revisão" : "Execução"}
          prazo={projeto.prazoEtapa}
          ativa
          dias={dias}
          atrasado={atrasado}
        />
      ) : (<>
        {/* Executor */}
        <PessoaRow
          icon={estado === "execucao" ? "✏️" : estado === "ajustes" ? "⚠️" : "✓"}
          nome={executor}
          funcao={estado === "ajustes" ? "Ajustes" : "Execução"}
          prazo={projeto.prazoExecutor}
          ativa={estado === "execucao" || estado === "ajustes"}
          concluida={estado === "revisao"}
          rejeitada={estado === "ajustes"}
          dias={diasRestantes(projeto.prazoExecutor)}
        />
        {/* Revisor */}
        <PessoaRow
          icon={estado === "revisao" ? "🔍" : "·"}
          nome={revisor}
          funcao={estado === "ajustes" ? "Aguardando correção" : "Revisão"}
          prazo={estado !== "ajustes" ? projeto.prazoRevisor : null}
          ativa={estado === "revisao"}
          inativa={estado !== "revisao"}
          topBorder
          dias={diasRestantes(projeto.prazoRevisor)}
        />
      </>)}
    </div>
  );
}

// ─── Linha de pessoa (executor ou revisor) ─────────────────
function PessoaRow({ icon, nome, funcao, prazo, ativa, concluida, inativa, rejeitada, topBorder, dias }) {
  let corNome = "#262421", corFuncao = "#6b7280", corPrazo = "#6b7280", fontWeightPrazo = 400;
  if (concluida || inativa) { corNome = "#6b7280"; corFuncao = "#9ca3af"; corPrazo = "#9ca3af"; }
  if (rejeitada) { corNome = "#92400e"; corFuncao = "#b45309"; corPrazo = "#b45309"; fontWeightPrazo = 600; }
  if (ativa && dias != null) {
    if (dias < 0) { corPrazo = "#dc2626"; fontWeightPrazo = 600; }
    else if (dias <= 3) { corPrazo = "#d97706"; fontWeightPrazo = 600; }
  }

  const prazoTxt = (() => {
    if (!prazo) return "";
    if (dias == null) return "prazo " + fmtDataBR(prazo);
    if (dias < 0) return `atrasado ${Math.abs(dias)} dias`;
    if (dias === 0) return "vence hoje";
    if (dias <= 5) return `faltam ${dias} dias`;
    return "prazo " + fmtDataBR(prazo);
  })();

  return (
    <div style={{
      display:"flex", flexDirection:"column", gap:1,
      ...(topBorder ? { marginTop:6, paddingTop:6, borderTop:"1px dashed #f3f4f6" } : {}),
    }}>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:8 }}>
        <span style={{ fontSize:11.5, lineHeight:1.3, color: corNome }}>
          <span style={{ display:"inline-block", width:14, fontSize:10, textAlign:"center", marginRight:4 }}>{icon}</span>
          <strong style={{ fontWeight:600 }}>{nome}</strong>
          <span style={{ color: corFuncao, fontWeight:400 }}> — {funcao}</span>
        </span>
        {prazoTxt && (
          <span style={{ fontSize:10.5, whiteSpace:"nowrap", color: corPrazo, fontWeight: fontWeightPrazo }}>
            {prazoTxt}
          </span>
        )}
      </div>
    </div>
  );
}

function motivoPadrao(colKey) {
  switch (colKey) {
    case "briefing":      return "Aguardando cliente preencher";
    case "prefeitura":    return "Aguardando análise da prefeitura";
    default: return "Aguardando";
  }
}

// ═══════════════════════════════════════════════════════════════
// MÓDULO OBRAS (stub — será desenvolvido em fase posterior)
// ═══════════════════════════════════════════════════════════════
function Obras({ data, save }) {
  const obras = data.obras || [];
  const clientes = data.clientes || [];
  const [filtro, setFiltro] = useState("andamento"); // "andamento" | "concluidas" | "todas"
  const [obraAbertaId, setObraAbertaId] = useState(null);
  const isMobile = typeof window !== "undefined" && window.innerWidth < 768;
  // A Entrada aberta daqui, antes de escolher a obra: a nota chega na mão e
  // entra; de qual obra ela é se diz depois de ler. Quando a pessoa segue,
  // guardamos o que ela montou e abrimos a obra já com isso na mão.
  const [entradaPendente, setEntradaPendente] = useState(null);
  // O que a Entrada daqui lançou numa obra: a obra abre só o tempo de
  // gravar e a página volta para a Entrada, que mostra isto.
  const [confirmacaoEntrada, setConfirmacaoEntrada] = useState(null);
  const [busca, setBusca] = useState("");
  const [buscaFocada, setBuscaFocada] = useState(false);
  const perm = typeof getPermissoes === "function" ? getPermissoes() : { podeGerenciarObra: true };

  function nomeCliente(clienteId) {
    return clientes.find(c => c.id === clienteId)?.nome || "—";
  }

  async function concluirObra(obra) {
    const ok = await dialogo.confirmar({
      titulo: `Concluir obra de ${nomeCliente(obra.clienteId)}?`,
      mensagem: "A obra será marcada como concluída e o cliente começará a contar 3 meses para inativação automática (se não tiver outro serviço ativo).",
      confirmar: "Concluir",
    });
    if (!ok) return;
    const agora = new Date().toISOString();
    const novasObras = obras.map(o =>
      o.id === obra.id ? { ...o, status: "concluida", concluidaEm: agora } : o
    );
    save({ ...data, obras: novasObras }).catch(console.error);
  }

  async function reabrirObra(obra) {
    const ok = await dialogo.confirmar({
      titulo: "Reabrir esta obra?",
      mensagem: "Ela voltará para 'Em andamento'.",
      confirmar: "Reabrir",
    });
    if (!ok) return;
    const novasObras = obras.map(o =>
      o.id === obra.id ? { ...o, status: "em_andamento", concluidaEm: null } : o
    );
    save({ ...data, obras: novasObras }).catch(console.error);
  }

  async function excluirObra(obra) {
    const ok = await dialogo.confirmar({
      titulo: `Excluir obra de ${nomeCliente(obra.clienteId)}?`,
      mensagem: "Esta ação não pode ser desfeita.",
      confirmar: "Excluir",
      destrutivo: true,
    });
    if (!ok) return;
    const novasObras = obras.filter(o => o.id !== obra.id);
    save({ ...data, obras: novasObras }).catch(console.error);
  }

  const obrasFiltradas = obras.filter(o => {
    if (filtro === "andamento" && o.status === "concluida") return false;
    if (filtro === "concluidas" && o.status !== "concluida") return false;
    const termo = semAcento(busca);
    if (!termo) return true;
    const alvo = semAcento([o.nome, o.referencia, nomeCliente(o.clienteId), o.cidade].filter(Boolean).join(" "));
    // Cada palavra digitada tem que aparecer: "cobop reforma" acha a obra
    // mesmo com o cliente e o nome em pontas opostas da linha.
    return termo.split(/\s+/).every(w => alvo.indexOf(w) >= 0);
  });

  const totais = {
    andamento: obras.filter(o => o.status !== "concluida").length,
    concluidas: obras.filter(o => o.status === "concluida").length,
    todas: obras.length,
  };

  const pillStyle = (ativa) => ({
    padding: "6px 14px", borderRadius: 7, fontSize: 12,
    border: "1.5px solid " + (ativa ? "#0474f4" : "rgba(38,36,33,0.16)"),
    background: "#fff",
    color: ativa ? "#0474f4" : "#4b5563",
    cursor: "pointer", fontFamily: "inherit", fontWeight: ativa ? 600 : 400,
  });

  // Obras vigentes, com o nome do cliente junto: duas obras podem se chamar
  // "Reforma", e o que as separa na lista é de quem elas são.
  const obrasVigentes = obras
    .filter(o => o && o.status !== "concluida" && clientes.some(c => c.id === o.clienteId))
    .map(o => ({ id: o.id, nome: o.nome || o.referencia || "Obra", clienteNome: nomeCliente(o.clienteId) }));

  function seguirDaEntradaDeObras(carga) {
    const alvo = (carga && carga.obraId) || "";
    if (!alvo) return;
    setConfirmacaoEntrada(null);
    setEntradaPendente(carga);
    setObraAbertaId(alvo);
    return (carga.destino === "lancar" || carga.destino === "despesa") ? { pendente: true } : undefined;
  }

  // A busca compara sem acento e sem caixa, pelo nome da obra, pelo cliente e
  // pela referência — é por qualquer um dos três que se procura uma obra.
  // Declarada como function de propósito: `obrasFiltradas` usa isto algumas
  // linhas ACIMA, e um const aí morreria na zona morta temporal — tela branca.
  function semAcento(s) {
    return String(s == null ? "" : s)
      .normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
  }

  // Obra aberta: mesma tela da obra que existe dentro do cliente
  // (GestaoObraPanel → detalhe: orçamento, planejamento, contratos, cronograma).
  const obraAberta = obraAbertaId ? obras.find(o => o.id === obraAbertaId) : null;
  const clienteDaObra = obraAberta ? clientes.find(c => c.id === obraAberta.clienteId) : null;
  if (obraAberta && clienteDaObra && typeof GestaoObraPanel === "function") {
    // No celular, 28px de cada lado somados às bordas das caixas de dentro
    // deixavam a cotação com dois terços da tela.
    return (
      <PageContainer padding={isMobile ? "12px 10px 24px" : undefined}>
        <div style={{ marginBottom: 16 }}>
          <h2 style={{ color:"#111827", fontWeight:700, fontSize:22, margin:0, letterSpacing:-0.5 }}>{clienteDaObra.nome}</h2>
          <div style={{ color:"#4b5563", fontSize:13, marginTop:4 }}>{obraAberta.nome || obraAberta.referencia || "Obra"}</div>
        </div>
        <GestaoObraPanel key={obraAberta.id} cliente={clienteDaObra} data={data} save={save} isMobile={isMobile}
          obraInicial={obraAberta} entradaInicial={entradaPendente}
          aoTerminarEntrada={(r) => { setEntradaPendente(null); setObraAbertaId(null); setConfirmacaoEntrada({ ...(r || {}), em: Date.now() }); }}
          onSairDaObra={() => { setEntradaPendente(null); setObraAbertaId(null); }} />
      </PageContainer>
    );
  }

  return (
    <PageContainer>
      <div style={{ marginBottom:16 }}>
        <h2 style={{ color:"#111827", fontWeight:700, fontSize:22, margin:0, letterSpacing:-0.5 }}>Obras</h2>
        <div style={{ color:"#4b5563", fontSize:13, marginTop:4 }}>Gestão de obras em execução</div>
      </div>

      {/* A Entrada não é mais um botão que abre uma telinha: ela É o alto da
          página. Quem chega aqui chega com uma nota na mão — o campo já está
          aberto esperando, e a lista de obras fica embaixo. */}
      {perm.podeGerenciarObra && obrasVigentes.length > 0 && typeof EntradaDaObra === "function" && (
        <EntradaDaObra data={data} save={save} obras={obrasVigentes} isMobile={isMobile}
          usuario={(typeof getUsuarioAtual === "function" ? getUsuarioAtual() : null)}
          embutido aoSeguir={seguirDaEntradaDeObras} confirmacao={confirmacaoEntrada} />
      )}

      {/* Busca dinâmica: filtra enquanto se digita, sem botão nenhum. */}
      <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:12,
        border: "1.5px solid " + (buscaFocada ? "rgba(4,116,244,0.55)" : "rgba(38,36,33,0.12)"),
        borderRadius: 999, background:"#fff", padding: isMobile ? "8px 14px" : "9px 16px",
        transition: "border-color .15s, box-shadow .15s",
        boxShadow: buscaFocada ? "0 0 0 4px rgba(4,116,244,0.10)" : "none" }}>
        <span style={{ color: buscaFocada ? "#0474f4" : "#9ca3af", display:"flex", flexShrink:0 }}>
          <IconeLupa tamanho={17} />
        </span>
        <input value={busca} onChange={(e) => setBusca(e.target.value)}
          onFocus={() => setBuscaFocada(true)} onBlur={() => setBuscaFocada(false)}
          placeholder="Procurar obra pelo nome ou pelo cliente…"
          style={{ flex:1, minWidth:0, border:"none", outline:"none", background:"transparent",
            fontFamily:"inherit", fontSize: isMobile ? 16 : 14, color:"#111827" }} />
        {busca && (
          <button type="button" onClick={() => setBusca("")} title="Limpar"
            style={{ border:"none", background:"none", color:"#9ca3af", cursor:"pointer",
              fontFamily:"inherit", fontSize:16, lineHeight:1, padding:0 }}>×</button>
        )}
      </div>

      {/* Filtros */}
      <div style={{ display:"flex", gap:8, marginBottom:16, flexWrap:"wrap" }}>
        <button onClick={() => setFiltro("andamento")} style={pillStyle(filtro==="andamento")}>
          Em andamento {totais.andamento > 0 && <span style={{ opacity:0.7, marginLeft:4 }}>{totais.andamento}</span>}
        </button>
        <button onClick={() => setFiltro("concluidas")} style={pillStyle(filtro==="concluidas")}>
          Concluídas {totais.concluidas > 0 && <span style={{ opacity:0.7, marginLeft:4 }}>{totais.concluidas}</span>}
        </button>
        <button onClick={() => setFiltro("todas")} style={pillStyle(filtro==="todas")}>
          Todas {totais.todas > 0 && <span style={{ opacity:0.7, marginLeft:4 }}>{totais.todas}</span>}
        </button>
      </div>

      {/* Lista */}
      {obrasFiltradas.length === 0 ? (
        <div style={{
          marginTop: 20, padding: "48px 24px", textAlign: "center",
          border: "1px dashed rgba(38,36,33,0.18)", borderRadius: 14, background: "#fafafa",
        }}>
          <div style={{ color:"#4b5563", fontSize:13 }}>
            {busca ? `Nenhuma obra para “${busca}”.` : (
              <>
                {filtro === "andamento" && "Nenhuma obra em andamento."}
                {filtro === "concluidas" && "Nenhuma obra concluída ainda."}
                {filtro === "todas" && "Nenhuma obra cadastrada."}
              </>
            )}
          </div>
          {!busca && (
            <div style={{ color:"#4b5563", fontSize:12, marginTop:6, maxWidth:440, margin:"6px auto 0" }}>
              Obras aparecem aqui automaticamente quando um projeto é finalizado na etapa <strong style={{ color:"#4b5563" }}>Engenharia</strong> do Kanban de Projetos.
            </div>
          )}
        </div>
      ) : (
        <div style={{ display:"flex", flexDirection:"column", gap:8, maxWidth:960 }}>
          {obrasFiltradas.map(obra => {
            const concluida = obra.status === "concluida";
            const podeAbrir = clientes.some(c => c.id === obra.clienteId);

            return (
              <div key={obra.id} role={podeAbrir ? "button" : undefined} tabIndex={podeAbrir ? 0 : undefined}
                onClick={() => podeAbrir && setObraAbertaId(obra.id)}
                onKeyDown={(e) => { if (podeAbrir && (e.key === "Enter" || e.key === " ")) { e.preventDefault(); setObraAbertaId(obra.id); } }}
                style={{
                  background: concluida ? "#fafafa" : "#fff",
                  border:"1px solid rgba(38,36,33,0.14)", borderRadius:9,
                  padding:"12px 16px", cursor: podeAbrir ? "pointer" : "default",
                  display:"grid", gridTemplateColumns:"1fr auto", gap:16, alignItems:"center",
                }}>
                <div style={{ minWidth:0, display:"flex", alignItems:"center", gap:10, flexWrap:"wrap" }}>
                  <div style={{ fontSize:14, fontWeight:600, color:"#111827" }}>{nomeCliente(obra.clienteId)}</div>
                  <div style={{ fontSize:13, color:"#4b5563" }}>{obra.nome || obra.referencia || "Obra"}</div>
                  {concluida && (
                    <span style={{ fontSize:10, fontWeight:600, textTransform:"uppercase", letterSpacing:0.5, padding:"2px 7px", borderRadius:4, background:"#f0fdf4", color:"#16a34a" }}>
                      Concluída
                    </span>
                  )}
                </div>
                <div style={{ display:"flex", gap:6 }} onClick={(e) => e.stopPropagation()}>
                  {!concluida && (
                    <button onClick={() => concluirObra(obra)}
                      style={{ fontSize:11.5, color:"#16a34a", background:"#fff", border:"1px solid #bbf7d0", borderRadius:6, padding:"5px 10px", cursor:"pointer", fontFamily:"inherit", fontWeight:500 }}>
                      ✓ Concluir
                    </button>
                  )}
                  {concluida && (
                    <button onClick={() => reabrirObra(obra)}
                      style={{ fontSize:11.5, color:"#4b5563", background:"#fff", border:"1.5px solid rgba(38,36,33,0.16)", borderRadius:6, padding:"5px 10px", cursor:"pointer", fontFamily:"inherit" }}>
                      Reabrir
                    </button>
                  )}
                  <button onClick={() => excluirObra(obra)}
                    style={{ fontSize:11.5, color:"#dc2626", background:"#fff", border:"1px solid #fecaca", borderRadius:6, padding:"5px 10px", cursor:"pointer", fontFamily:"inherit" }}>
                    Excluir
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </PageContainer>
  );
}



// ═══════════════════════════════════════════════════════════════
// MÓDULO FINANCEIRO
// ═══════════════════════════════════════════════════════════════
function Financeiro({ data, save }) {
  const receitas = data.receitasFinanceiro || [];
  const [busca, setBusca]           = useState("");
  const [filtroTipo, setFiltroTipo] = useState("todas");
  const [editDesc, setEditDesc]     = useState(null);
  const [selecionados, setSelecionados] = useState(new Set());
  const [filtroCol, setFiltroCol]   = useState(null);
  const [filtroVals, setFiltroVals] = useState({});

  function exportarCSV() {
    const cols = [
      "Codigo","Cod. Cliente","Nome Cliente","Categoria","Produto","Fornecedor",
      "Descricao","Tipo Conta","Conta Contabil 1","Sub Conta 1","Sub Conta 2",
      "Sub Conta 3","Sub Conta 4","Sub Conta 5",
      "Comprovante","Competencia","Recebimento","Valor",
      "Data Lancamento","Periodo Contabil","Periodo Caixa"
    ];
    const rows = receitas.map(r => [
      r.codigo||"", r.clienteId||"", r.cliente||"", r.categoria||"", r.produto||"", r.fornecedor||"",
      r.descricao||"", r.tipoConta||"", r.contabil1||"", r.subContabil1||"", r.subContabil2||"",
      r.subContabil3||"", r.subContabil4||"", r.subContabil5||"",
      r.nComprovante||"", r.competencia||"", r.recebimento||"", r.valor||0,
      r.dataLancamento||"", r.periodoContabil||"", r.periodoCaixa||""
    ]);
    const esc = v => { const s = String(v).replace(/"/g,'""'); return s.includes(";")||s.includes("\n")||s.includes('"') ? '"'+s+'"' : s; };
    const csv = [cols,...rows].map(row => row.map(esc).join(";")).join("\n");
    const url = "data:text/csv;charset=utf-8,\uFEFF" + encodeURIComponent(csv);
    const a = document.createElement("a"); a.href=url; a.download="financeiro.csv";
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
  }

  function excluirSelecionados() {
    const novos = receitas.filter((_r, i) => !selecionados.has(i));
    save({...data, receitasFinanceiro: novos});
    setSelecionados(new Set());
  }

  function salvarDesc(idx, novaDesc) {
    const novos = receitas.map((r,i) => i===idx ? {...r, descricao:novaDesc} : r);
    save({...data, receitasFinanceiro: novos});
    setEditDesc(null);
  }

  function valoresUnicos(campo) {
    return [...new Set(receitas.map(r => r[campo]||"").filter(Boolean))].sort();
  }

  function toggleFiltroVal(campo, val) {
    setFiltroVals(prev => {
      const set = new Set(prev[campo] || []);
      if (set.has(val)) set.delete(val); else set.add(val);
      return { ...prev, [campo]: set };
    });
  }

  const fmtV = v => (v||0).toLocaleString("pt-BR", { minimumFractionDigits:2, maximumFractionDigits:2 });
  const fmtD = iso => iso ? new Date(iso+"T00:00:00").toLocaleDateString("pt-BR") : "--";

  const totalContabil = receitas.filter(r=>r.contabil1==="Receita Total").reduce((s,r)=>s+(r.valor||0),0);
  const totalCaixa    = receitas.filter(r=>r.contabil1==="Caixa" && r.recebimento==="Recebido").reduce((s,r)=>s+(r.valor||0),0);
  const totalReceber  = receitas.filter(r=>r.contabil1==="Caixa" && r.recebimento==="A Receber").reduce((s,r)=>s+(r.valor||0),0);
  const temFiltroAtivo = Object.values(filtroVals).some(s => s && s.size > 0);

  const lancs = receitas.filter(r => {
    if (filtroTipo==="contabil" && r.contabil1!=="Receita Total") return false;
    if (filtroTipo==="caixa"    && r.contabil1!=="Caixa") return false;
    for (const [campo, set] of Object.entries(filtroVals)) {
      if (set && set.size > 0 && !set.has(r[campo]||"")) return false;
    }
    if (busca) {
      const b = busca.toLowerCase();
      return (r.cliente||"").toLowerCase().includes(b) ||
             (r.descricao||"").toLowerCase().includes(b) ||
             (r.codigo||"").toLowerCase().includes(b);
    }
    return true;
  });

  const thS = { padding:"6px 8px", fontSize:10, fontWeight:600, textTransform:"uppercase",
    letterSpacing:0.4, whiteSpace:"nowrap", color:"#64748b",
    background:"#0a1122", borderBottom:"1px solid #1e293b", textAlign:"left" };
  const tdS = { padding:"6px 8px", fontSize:11, whiteSpace:"nowrap",
    borderBottom:"1px solid #0f172a", color:"#94a3b8" };

  // Colunas filtaveis: [label, campo]
  const COLS_FILTER = [
    ["Categoria","categoria"],["Produto","produto"],["Fornecedor","fornecedor"],
    ["Tipo Conta","tipoConta"],["Conta Contabil 1","contabil1"],
    ["Sub Conta 1","subContabil1"],["Sub Conta 2","subContabil2"],
    ["Competencia","competencia"],["Recebimento","recebimento"],
  ];

  return (
    <PageContainer>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:16 }}>
        <div>
          <h2 style={{ color:"#f1f5f9", fontWeight:900, fontSize:22, margin:0 }}>Financeiro</h2>
          <p style={{ color:"#64748b", fontSize:13, marginTop:4 }}>Livro de lancamentos</p>
        </div>
      </div>

      {/* Cards */}
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:14, marginBottom:20 }}>
        {[
          { label:"Receita Contabil",  v:totalContabil, c:"#3b82f6", sub: receitas.filter(r=>r.contabil1==="Receita Total").length + " lancamentos" },
          { label:"Caixa Recebido",    v:totalCaixa,    c:"#10b981", sub: receitas.filter(r=>r.recebimento==="Recebido").length + " lancamentos" },
          { label:"A Receber",         v:totalReceber,  c:"#f59e0b", sub: receitas.filter(r=>r.recebimento==="A Receber").length + " lancamentos" },
        ].map(c => (
          <div key={c.label} style={{ background:"#0d1526", border:"1px solid #1e293b", borderRadius: 14, padding:"16px 20px" }}>
            <div style={{ color:"#64748b", fontSize:11, fontWeight:600, textTransform:"uppercase", letterSpacing:0.5, marginBottom:6 }}>{c.label}</div>
            <div style={{ color:c.c, fontWeight:800, fontSize:20 }}>R$ {fmtV(c.v)}</div>
            <div style={{ color:"#334155", fontSize:11, marginTop:4 }}>{c.sub}</div>
          </div>
        ))}
      </div>

      {/* Filtros */}
      <div style={{ display:"flex", gap:10, marginBottom:12, alignItems:"center", flexWrap:"wrap" }}>
        <input value={busca} onChange={e=>setBusca(e.target.value)} placeholder="Buscar cliente, codigo, descricao..."
          style={{ background:"#0a1122", border:"1px solid #1e293b", borderRadius:6, color:"#f1f5f9",
            padding:"6px 12px", fontSize:12, outline:"none", fontFamily:"inherit", width:260 }} />
        {[["todas","Todos"],["contabil","Contabil"],["caixa","Caixa"]].map(([v,l]) => (
          <button key={v} onClick={()=>setFiltroTipo(v)}
            style={{ background:filtroTipo===v?"#1e3a5f":"transparent",
              color:filtroTipo===v?"#60a5fa":"#64748b",
              border:"1px solid "+(filtroTipo===v?"#2563eb":"#1e293b"),
              borderRadius:6, padding:"5px 14px", fontSize:11, fontWeight:600,
              cursor:"pointer", fontFamily:"inherit" }}>{l}</button>
        ))}
        <span style={{ color:"#334155", fontSize:11, marginLeft:"auto" }}>{lancs.length} registro{lancs.length!==1?"s":""}</span>
        <button onClick={exportarCSV} disabled={receitas.length===0}
          style={{ background:"#164e2a", border:"1px solid #16a34a", borderRadius:6,
            color:"#4ade80", padding:"5px 14px", fontSize:11, fontWeight:600,
            cursor:receitas.length===0?"not-allowed":"pointer", fontFamily:"inherit", opacity:receitas.length===0?0.4:1 }}>
          Exportar CSV
        </button>
        {selecionados.size > 0 && (
          <button onClick={excluirSelecionados}
            style={{ background:"rgba(248,113,113,0.15)", border:"1px solid #f87171", borderRadius:6,
              color:"#f87171", padding:"5px 14px", fontSize:11, fontWeight:600,
              cursor:"pointer", fontFamily:"inherit" }}>
            Excluir {selecionados.size} selecionado{selecionados.size!==1?"s":""}
          </button>
        )}
        {temFiltroAtivo && (
          <button onClick={()=>setFiltroVals({})}
            style={{ background:"rgba(99,102,241,0.12)", border:"1px solid #6366f1",
              borderRadius:6, color:"#818cf8", padding:"5px 14px", fontSize:11,
              fontWeight:600, cursor:"pointer", fontFamily:"inherit" }}>
            Limpar filtros
          </button>
        )}
      </div>

      {/* Dropdown filtro por coluna */}
      {filtroCol && (
        <div style={{ background:"#0f172a", border:"1px solid #334155", borderRadius: 14,
          padding:"14px 16px", maxWidth:280, marginBottom:10, boxShadow:"0 8px 24px rgba(0,0,0,0.5)" }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:10 }}>
            <span style={{ color:"#e2e8f0", fontSize:12, fontWeight:700 }}>Filtrar: {filtroCol.label}</span>
            <div style={{ display:"flex", gap:8 }}>
              <button onClick={()=>setFiltroVals(prev=>{const n={...prev};delete n[filtroCol.campo];return n;})}
                style={{ background:"transparent", border:"none", color:"#64748b", fontSize:11, cursor:"pointer", fontFamily:"inherit" }}>
                Limpar
              </button>
              <button onClick={()=>setFiltroCol(null)}
                style={{ background:"transparent", border:"none", color:"#64748b", fontSize:16, cursor:"pointer", lineHeight:1 }}>
                x
              </button>
            </div>
          </div>
          <div style={{ display:"flex", flexDirection:"column", gap:4, maxHeight:180, overflowY:"auto" }}>
            {valoresUnicos(filtroCol.campo).map(val => {
              const ativo = filtroVals[filtroCol.campo]?.has(val);
              return (
                <label key={val} style={{ display:"flex", alignItems:"center", gap:8, cursor:"pointer",
                  padding:"4px 6px", borderRadius:5, background:ativo?"rgba(59,130,246,0.12)":"transparent" }}>
                  <input type="checkbox" checked={!!ativo}
                    onChange={()=>toggleFiltroVal(filtroCol.campo, val)}
                    style={{ accentColor:"#3b82f6", cursor:"pointer" }} />
                  <span style={{ color:ativo?"#60a5fa":"#94a3b8", fontSize:12 }}>{val}</span>
                </label>
              );
            })}
            {valoresUnicos(filtroCol.campo).length===0 && (
              <span style={{ color:"#334155", fontSize:11 }}>Sem valores</span>
            )}
          </div>
        </div>
      )}

      {/* Tabela */}
      {lancs.length === 0 ? (
        <div style={{ textAlign:"center", padding:"60px 0", color:"#334155" }}>
          <div style={{ fontSize:13 }}>Nenhum lancamento. Confirme orcamentos como Ganho para gerar receitas.</div>
        </div>
      ) : (
        <div style={{ overflowX:"auto", borderRadius: 14, border:"1px solid #1e293b" }}>
          <table style={{ borderCollapse:"collapse", width:"100%", minWidth:2000 }}>
            <thead>
              <tr>
                {[
                  ["",1,"#0a1122","#475569"],
                  ["Identificacao",3,"#0a1122","#475569"],
                  ["Partes",4,"#0a1122","#475569"],
                  ["Descricao",1,"#0a1122","#475569"],
                  ["Plano de Contas",8,"#0d1a2e","#60a5fa"],
                  ["Comprovante",2,"#0a1122","#475569"],
                  ["Financeiro",5,"#0a1122","#475569"],
                ].map(([lbl,span,bg,cor])=>(
                  <th key={lbl||"chk"} colSpan={span}
                    style={{...thS,background:bg,color:cor,textAlign:"center",borderRight:"1px solid #1e293b"}}>
                    {lbl}
                  </th>
                ))}
              </tr>
              <tr>
                {/* Checkbox todos */}
                <th style={{...thS, width:36, textAlign:"center"}}>
                  <input type="checkbox"
                    checked={lancs.length>0 && lancs.every(r=>selecionados.has(receitas.indexOf(r)))}
                    onChange={e=>setSelecionados(e.target.checked?new Set(lancs.map(r=>receitas.indexOf(r))):new Set())}
                    style={{ cursor:"pointer", accentColor:"#3b82f6" }} />
                </th>
                {/* Identificacao */}
                {["Cod. Lanc.","Cod. Cliente","Data Lanc."].map(h=>(
                  <th key={h} style={thS}>{h}</th>
                ))}
                {/* Partes -- com filtro */}
                {[["Nome do Cliente","cliente"],["Categoria","categoria"],["Produto","produto"],["Fornecedor","fornecedor"]].map(([h,campo])=>{
                  const ativo = filtroVals[campo]?.size > 0;
                  return (
                    <th key={h} onClick={()=>setFiltroCol(filtroCol?.campo===campo?null:{campo,label:h})}
                      style={{...thS,borderLeft:"1px solid #1e293b",cursor:"pointer",userSelect:"none",
                        color:ativo?"#60a5fa":"#64748b",background:ativo?"#0d1a2e":undefined}}>
                      {h}{ativo?" [F]":""}
                    </th>
                  );
                })}
                {/* Descricao */}
                <th style={{...thS,borderLeft:"1px solid #1e293b"}}>Descricao do Lancamento</th>
                {/* Plano de contas -- com filtro */}
                {[["Tipo Conta","tipoConta"],["Conta Contabil 1","contabil1"],["Sub Conta 1","subContabil1"],
                  ["Sub Conta 2","subContabil2"],["Sub Conta 3",""],["Sub Conta 4",""],["Sub Conta 5",""],
                  ["Competencia","competencia"]].map(([h,campo])=>{
                  const ativo = campo && filtroVals[campo]?.size > 0;
                  return (
                    <th key={h} onClick={campo?()=>setFiltroCol(filtroCol?.campo===campo?null:{campo,label:h}):undefined}
                      style={{...thS,borderLeft:"1px solid #1e293b",background:ativo?"#131f3a":"#0d1a2e",
                        color:ativo?"#60a5fa":"#475569",cursor:campo?"pointer":"default",userSelect:"none"}}>
                      {h}{ativo?" [F]":""}
                    </th>
                  );
                })}
                {/* Comprovante */}
                {["No Comprovante","No Nota"].map(h=>(
                  <th key={h} style={{...thS,borderLeft:"1px solid #1e293b"}}>{h}</th>
                ))}
                {/* Financeiro -- com filtro em Recebimento */}
                {[["Recebimento","recebimento"],["Valor (R$)",""],["Data Lancamento",""],["Periodo Contabil",""],["Periodo Caixa",""]].map(([h,campo])=>{
                  const ativo = campo && filtroVals[campo]?.size > 0;
                  return (
                    <th key={h} onClick={campo?()=>setFiltroCol(filtroCol?.campo===campo?null:{campo,label:h}):undefined}
                      style={{...thS,borderLeft:"1px solid #1e293b",
                        color:ativo?"#60a5fa":"#64748b",cursor:campo?"pointer":"default",userSelect:"none"}}>
                      {h}{ativo?" [F]":""}
                    </th>
                  );
                })}
              </tr>
            </thead>
            <tbody>
              {lancs.map((r, idx) => {
                const realIdx = receitas.indexOf(r);
                const isEdit  = editDesc?.idx === realIdx;
                const isCaixa = r.contabil1 === "Caixa";
                const isReceb = r.recebimento === "Recebido";
                const isAReceber = r.recebimento === "A Receber";
                const rowBg = selecionados.has(realIdx) ? "rgba(59,130,246,0.1)"
                  : isCaixa ? (idx%2===0?"#060d1a":"#080e1a")
                  : (idx%2===0?"#0a1122":"#0c1420");
                return (
                  <tr key={r.id||idx} style={{ background:rowBg }}>
                    <td style={{...tdS,width:36,textAlign:"center"}}>
                      <input type="checkbox" checked={selecionados.has(realIdx)}
                        onChange={e=>setSelecionados(prev=>{const n=new Set(prev);if(e.target.checked)n.add(realIdx);else n.delete(realIdx);return n;})}
                        style={{ cursor:"pointer", accentColor:"#3b82f6" }} />
                    </td>
                    <td style={{...tdS,fontFamily:"monospace",fontSize:10,color:"#475569"}}>{r.codigo||"--"}</td>
                    <td style={{...tdS,fontFamily:"monospace",fontSize:10,color:"#475569"}}>{r.clienteId||"--"}</td>
                    <td style={{...tdS}}>{fmtD(r.dataLancamento)}</td>
                    {/* Partes */}
                    <td style={{...tdS,borderLeft:"1px solid #1e293b",color:"#e2e8f0",maxWidth:140,overflow:"hidden",textOverflow:"ellipsis"}}>{r.cliente||"--"}</td>
                    <td style={{...tdS}}>{r.categoria||"--"}</td>
                    <td style={{...tdS}}>{r.produto||"--"}</td>
                    <td style={{...tdS,maxWidth:130,overflow:"hidden",textOverflow:"ellipsis"}}>{r.fornecedor||"--"}</td>
                    {/* Descricao */}
                    <td style={{...tdS,borderLeft:"1px solid #1e293b",maxWidth:200}}>
                      {isEdit ? (
                        <input autoFocus defaultValue={r.descricao}
                          onBlur={e=>salvarDesc(realIdx,e.target.value)}
                          onKeyDown={e=>{if(e.key==="Enter")salvarDesc(realIdx,e.target.value);if(e.key==="Escape")setEditDesc(null);}}
                          style={{background:"#0a1122",border:"1px solid #2563eb",borderRadius:4,color:"#f1f5f9",
                            padding:"3px 6px",fontSize:11,outline:"none",fontFamily:"inherit",width:"100%"}} />
                      ):(
                        <span onClick={()=>setEditDesc({idx:realIdx})}
                          style={{color:"#94a3b8",cursor:"pointer",display:"block",maxWidth:200,
                            overflow:"hidden",textOverflow:"ellipsis",borderBottom:"1px dashed #1e293b"}}>
                          {r.descricao||"--"}
                        </span>
                      )}
                    </td>
                    {/* Plano de Contas */}
                    <td style={{...tdS,borderLeft:"1px solid #1e293b",background:"#0d1a2e",
                      color:r.tipoConta==="Conta Redutora"?"#f87171":"#10b981",fontWeight:600,fontSize:10}}>
                      {r.tipoConta||"--"}
                    </td>
                    <td style={{...tdS,background:"#0d1a2e",color:isCaixa?"#f59e0b":"#3b82f6",fontWeight:600}}>{r.contabil1||"--"}</td>
                    <td style={{...tdS,background:"#0d1a2e",color:"#64748b"}}>{r.subContabil1||"--"}</td>
                    <td style={{...tdS,background:"#0d1a2e",color:"#64748b"}}>{r.subContabil2||"--"}</td>
                    <td style={{...tdS,background:"#0d1a2e",color:"#334155"}}>{r.subContabil3||"--"}</td>
                    <td style={{...tdS,background:"#0d1a2e",color:"#334155"}}>{r.subContabil4||"--"}</td>
                    <td style={{...tdS,background:"#0d1a2e",color:"#334155"}}>{r.subContabil5||"--"}</td>
                    <td style={{...tdS,background:"#0d1a2e",
                      color:r.competencia==="Contabil"?"#a78bfa":isReceb?"#10b981":"#f59e0b"}}>
                      {r.competencia||"--"}
                    </td>
                    {/* Comprovante */}
                    <td style={{...tdS,borderLeft:"1px solid #1e293b",fontFamily:"monospace",fontSize:10}}>{r.nComprovante||"--"}</td>
                    <td style={{...tdS,fontFamily:"monospace",fontSize:10}}>{r.nNota||"--"}</td>
                    {/* Financeiro */}
                    <td style={{...tdS,borderLeft:"1px solid #1e293b",
                      color:isReceb?"#10b981":isAReceber?"#f59e0b":r.recebimento==="Conta contabil"?"#a78bfa":"#94a3b8"}}>
                      {r.recebimento||"--"}
                    </td>
                    <td style={{...tdS,fontWeight:700,textAlign:"right",color:"#10b981"}}>
                      R$ {fmtV(r.valor||0)}
                    </td>
                    <td style={{...tdS}}>{fmtD(r.dataLancamento)}</td>
                    <td style={{...tdS,color:r.periodoContabil?"#e2e8f0":"#334155"}}>{fmtD(r.periodoContabil)}</td>
                    <td style={{...tdS,color:r.periodoCaixa?"#10b981":"#334155"}}>{r.periodoCaixa?fmtD(r.periodoCaixa):"--"}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </PageContainer>
  );
}

// ═══════════════════════════════════════════════════════════════
// PRESTADORES DE SERVIÇO — cadastro de empreiteiros, eletricistas,
// pintores, gesseiros, lojas, esquadrias de alumínio etc.
// Reaproveita a coleção `data.fornecedores` dos dados antigos, mas o
// cadastro em si foi refeito do zero com campos mais simples.
// ═══════════════════════════════════════════════════════════════
// Espelha os prestadores de serviço do catálogo de insumos (grupo
// "Prestadores de serviços") — é por essa categoria que o gerador de
// contratos filtra a lista de contratados.
const CATEGORIAS_PRESTADOR = [
  "Carpinteiro", "Concreteira", "Eletricista", "Empreiteiro", "Encanador",
  "Esquadria de Alumínio", "Gesseiro", "Gestão de Obra",
  "Impermeabilizador", "Instalador de Aquecedores",
  "Instalador de Ar Condicionado", "Instalador de Equipamentos de Piscina",
  "Loja / Comércio", "Marceneiro", "Pedreiro", "Pintor", "Serralheiro",
  "Terraplanagem", "Outro",
];

// Paleta oficial do Vicke (grafite + cobre) — ver memória "vicke_paleta_cores".
const PS = {
  input:  { border:"1.5px solid rgba(38,36,33,0.16)", borderRadius:12, padding:"9px 12px", fontSize:13, color:"#111827", outline:"none", background:"#fff", fontFamily:"inherit", width:"100%", boxSizing:"border-box" },
  label:  { fontSize:12, color:"#4b5563", fontWeight:500, display:"block", marginBottom:5 },
  btn:    { background:"#262421", color:"#fff", border:"none", borderRadius:12, padding:"9px 20px", fontSize:13, fontWeight:600, cursor:"pointer", fontFamily:"inherit" },
  btnSec: { background:"#fff", color:"#111827", border:"1.5px solid rgba(38,36,33,0.16)", borderRadius:12, padding:"9px 16px", fontSize:13, cursor:"pointer", fontFamily:"inherit" },
  btnGhost: { background:"none", border:"none", color:"#4b5563", cursor:"pointer", fontFamily:"inherit", fontSize:13 },
  tag:    (cor) => ({ fontSize:11, fontWeight:600, padding:"2px 8px", borderRadius:6, background:cor+"18", color:cor }),
};

function PrestadoresServico({ data, save }) {
  const [view, setView] = useState("list");
  const [busca, setBusca] = useState("");
  const [filtroCategoria, setFiltroCategoria] = useState("");

  const emptyPrestador = {
    nome:"", tipo:"PJ", categoria:CATEGORIAS_PRESTADOR[0], cnpjCpf:"",
    cep:"", logradouro:"", numero:"", bairro:"", cidade:"", estado:"SP",
    representanteNome:"", representanteCpf:"",
    telefone:"", whatsapp:false, email:"", observacoes:"", ativo:true,
    pixTipo:"cnpj", pixChave:"", pixBeneficiario:"",
  };
  const [form, setForm] = useState(emptyPrestador);

  const prestadores = data.fornecedores || [];
  const filtrados = prestadores.filter(p => {
    const matchBusca = p.nome.toLowerCase().includes(busca.toLowerCase());
    const matchCategoria = !filtroCategoria || p.categoria === filtroCategoria;
    return matchBusca && matchCategoria;
  });

  function openNew() { setForm(emptyPrestador); setView("form"); }
  function openEdit(p) { setForm(p); setView("form"); }

  function salvar(e) {
    e.preventDefault();
    if (!form.nome?.trim()) { dialogo.alertar({ titulo: "Informe o nome", tipo: "aviso" }); return; }
    const novos = form.id
      ? prestadores.map(p => p.id === form.id ? form : p)
      : [...prestadores, { ...form, id: uid() }];
    save({ ...data, fornecedores: novos });
    setView("list");
  }

  async function remover(id) {
    const ok = await dialogo.confirmar({ titulo: "Remover prestador?", mensagem: "Esta ação não pode ser desfeita.", confirmar: "Remover", destrutivo: true });
    if (!ok) return;
    save({ ...data, fornecedores: prestadores.filter(p => p.id !== id) });
  }

  function waLink(telefone) {
    const num = (telefone||"").replace(/\D/g, "");
    const numero = num.startsWith("55") ? num : `55${num}`;
    return `https://wa.me/${numero}`;
  }

  async function buscarCEP(cep) {
    const clean = cep.replace(/\D/g, "");
    if (clean.length !== 8) return;
    try {
      const r = await fetch(`https://viacep.com.br/ws/${clean}/json/`);
      const d = await r.json();
      if (!d.erro) setForm(f => ({ ...f, logradouro: d.logradouro, bairro: d.bairro, cidade: d.localidade, estado: d.uf }));
    } catch {}
  }

  // LISTA
  if (view === "list") return (
    <div style={{ padding:"28px 32px", fontFamily:"'Inter', system-ui, -apple-system, sans-serif" }}>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:20, flexWrap:"wrap", gap:12 }}>
        <div>
          <h2 style={{ color:"#111827", fontWeight:700, fontSize:22, margin:0, letterSpacing:-0.5 }}>Prestadores de Serviços</h2>
          <div style={{ color:"#4b5563", fontSize:13, marginTop:4 }}>{prestadores.length} cadastrado{prestadores.length !== 1 ? "s" : ""}</div>
        </div>
        <button style={PS.btn} onClick={openNew}>+ Novo prestador</button>
      </div>

      <div style={{ display:"flex", gap:10, marginBottom:20, flexWrap:"wrap" }}>
        <input style={{ ...PS.input, maxWidth:280 }} placeholder="Buscar por nome..." value={busca} onChange={e=>setBusca(e.target.value)} />
        <Selecao style={{ ...PS.input, maxWidth:220, cursor:"pointer" }} value={filtroCategoria} onChange={e=>setFiltroCategoria(e.target.value)}>
          <option value="">Todas as categorias</option>
          {CATEGORIAS_PRESTADOR.map(c => <option key={c} value={c}>{c}</option>)}
        </Selecao>
      </div>

      {filtrados.length === 0 ? (
        <div style={{ padding:"40px 20px", textAlign:"center", color:"#4b5563", fontSize:13, border:"1px dashed rgba(38,36,33,0.18)", borderRadius:16, background:"#fafafa" }}>
          {prestadores.length === 0 ? "Nenhum prestador cadastrado." : "Nenhum resultado para essa busca."}{" "}
          {prestadores.length === 0 && <button onClick={openNew} style={{ background:"transparent", border:"none", color:"#0474f4", cursor:"pointer", padding:0, fontSize:13, fontFamily:"inherit", textDecoration:"underline" }}>Cadastrar o primeiro</button>}
        </div>
      ) : (
        <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill, minmax(260px, 1fr))", gap:14 }}>
          {filtrados.map(p => (
            <div key={p.id} style={{ border:"1px solid rgba(38,36,33,0.14)", borderRadius:16, padding:"16px 18px", background:"#fff", transition:"border-color 0.15s, box-shadow 0.15s" }}
              onMouseEnter={e=>{ e.currentTarget.style.borderColor="#0474f4"; e.currentTarget.style.boxShadow="0 0 0 3px rgba(4,116,244,0.12)"; }}
              onMouseLeave={e=>{ e.currentTarget.style.borderColor="rgba(38,36,33,0.14)"; e.currentTarget.style.boxShadow="none"; }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"start", gap:8, marginBottom:8 }}>
                <div style={{ fontSize:14, fontWeight:700, color:"#111827" }}>{p.nome}</div>
                {p.ativo === false && <span style={PS.tag("#9ca3af")}>Inativo</span>}
              </div>
              <span style={PS.tag("#0474f4")}>{p.categoria}</span>
              <div style={{ marginTop:10, display:"flex", flexDirection:"column", gap:4 }}>
                {p.cnpjCpf && <div style={{ fontSize:12.5, color:"#4b5563" }}>{p.tipo === "PF" ? "CPF" : "CNPJ"}: {p.cnpjCpf}</div>}
                {p.telefone && <div style={{ fontSize:12.5, color:"#4b5563" }}>{p.telefone}</div>}
                {p.email && <div style={{ fontSize:12.5, color:"#4b5563", overflow:"hidden", textOverflow:"ellipsis" }}>{p.email}</div>}
                {(p.cidade || p.estado) && <div style={{ fontSize:12.5, color:"#4b5563" }}>{p.cidade}{p.cidade && p.estado ? " — " : ""}{p.estado}</div>}
              </div>
              <div style={{ display:"flex", gap:8, marginTop:14 }}>
                {p.whatsapp && p.telefone && (
                  <a href={waLink(p.telefone)} target="_blank" rel="noopener noreferrer"
                    style={{ fontSize:12, color:"#fff", textDecoration:"none", background:"#16a34a", border:"1px solid #16a34a", borderRadius:12, padding:"5px 12px", fontWeight:600 }}>WhatsApp</a>
                )}
                <button onClick={()=>openEdit(p)} style={{ ...PS.btnSec, fontSize:12, padding:"5px 12px" }}>Editar</button>
                <button onClick={()=>remover(p.id)} style={{ ...PS.btnGhost, color:"#dc2626", fontSize:12 }}>Remover</button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  // FORMULÁRIO
  return (
    <div style={{ padding:"28px 32px", maxWidth:560, fontFamily:"'Inter', system-ui, -apple-system, sans-serif" }}>
      <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:24 }}>
        <button style={PS.btnGhost} onClick={()=>setView("list")}>← Voltar</button>
        <div style={{ fontSize:17, fontWeight:700, color:"#111827" }}>{form.id ? "Editar prestador" : "Novo prestador"}</div>
      </div>
      <form onSubmit={salvar}>
        <div style={{ marginBottom:14 }}>
          <label style={PS.label}>Tipo de pessoa</label>
          <div style={{ display:"flex", gap:8 }}>
            {[["PF","Pessoa física"],["PJ","Pessoa jurídica"]].map(([v,l])=>(
              <button type="button" key={v} onClick={()=>setForm({...form,tipo:v})}
                style={{ border:"1px solid rgba(38,36,33,0.16)", borderRadius:12, padding:"9px 18px", fontSize:13, fontWeight:form.tipo===v?600:400, background:form.tipo===v?"#262421":"#fff", color:form.tipo===v?"#fff":"#6b7280", cursor:"pointer", fontFamily:"inherit" }}>{l}</button>
            ))}
          </div>
        </div>
        <div style={{ marginBottom:14 }}>
          <label style={PS.label}>{form.tipo === "PJ" ? "Razão social" : "Nome completo"} *</label>
          <input style={PS.input} value={form.nome} onChange={e=>setForm({...form,nome:e.target.value})} placeholder={form.tipo === "PJ" ? "Nome da empresa" : "Nome da pessoa"} autoFocus />
        </div>
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12, marginBottom:14 }}>
          <div>
            <label style={PS.label}>Categoria</label>
            <Selecao style={{ ...PS.input, cursor:"pointer" }} value={form.categoria} onChange={e=>setForm({...form,categoria:e.target.value})}>
              {CATEGORIAS_PRESTADOR.map(c => <option key={c} value={c}>{c}</option>)}
            </Selecao>
          </div>
          <div>
            <label style={PS.label}>{form.tipo === "PJ" ? "CNPJ" : "CPF"}</label>
            <input style={PS.input} value={form.cnpjCpf} onChange={e=>setForm({...form,cnpjCpf:e.target.value})} placeholder={form.tipo === "PJ" ? "00.000.000/0001-00" : "000.000.000-00"} />
          </div>
        </div>

        <div style={{ marginBottom:6, marginTop:20 }}>
          <div style={{ fontSize:11, fontWeight:700, color:"#4b5563", textTransform:"uppercase", letterSpacing:1 }}>Endereço</div>
        </div>
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12, marginBottom:12 }}>
          <div>
            <label style={PS.label}>CEP</label>
            <input style={PS.input} value={form.cep} onChange={e=>{ setForm({...form,cep:e.target.value}); buscarCEP(e.target.value); }} placeholder="00000-000" />
          </div>
          <div>
            <label style={PS.label}>Número</label>
            <input style={PS.input} value={form.numero} onChange={e=>setForm({...form,numero:e.target.value})} />
          </div>
        </div>
        <div style={{ marginBottom:12 }}>
          <label style={PS.label}>Logradouro</label>
          <input style={PS.input} value={form.logradouro} onChange={e=>setForm({...form,logradouro:e.target.value})} />
        </div>
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:12, marginBottom:20 }}>
          <div>
            <label style={PS.label}>Bairro</label>
            <input style={PS.input} value={form.bairro} onChange={e=>setForm({...form,bairro:e.target.value})} />
          </div>
          <div>
            <label style={PS.label}>Cidade</label>
            <input style={PS.input} value={form.cidade} onChange={e=>setForm({...form,cidade:e.target.value})} />
          </div>
          <div>
            <label style={PS.label}>Estado</label>
            <Selecao style={{ ...PS.input, cursor:"pointer" }} value={form.estado} onChange={e=>setForm({...form,estado:e.target.value})}>
              {ESTADOS_BR.map(e => <option key={e}>{e}</option>)}
            </Selecao>
          </div>
        </div>

        {form.tipo === "PJ" && (
          <>
            <div style={{ marginBottom:6 }}>
              <div style={{ fontSize:11, fontWeight:700, color:"#4b5563", textTransform:"uppercase", letterSpacing:1 }}>Representante / sócio</div>
            </div>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12, marginBottom:20 }}>
              <div>
                <label style={PS.label}>Nome</label>
                <input style={PS.input} value={form.representanteNome} onChange={e=>setForm({...form,representanteNome:e.target.value})} />
              </div>
              <div>
                <label style={PS.label}>CPF</label>
                <input style={PS.input} value={form.representanteCpf} onChange={e=>setForm({...form,representanteCpf:e.target.value})} placeholder="000.000.000-00" />
              </div>
            </div>
          </>
        )}

        <div style={{ marginBottom:6 }}>
          <div style={{ fontSize:11, fontWeight:700, color:"#4b5563", textTransform:"uppercase", letterSpacing:1 }}>Contato</div>
        </div>
        <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12, marginBottom:14 }}>
          <div>
            <label style={PS.label}>Telefone</label>
            <input style={PS.input} value={form.telefone} onChange={e=>setForm({...form,telefone:e.target.value})} placeholder="(00) 00000-0000" />
          </div>
          <div>
            <label style={PS.label}>E-mail</label>
            <input style={PS.input} type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} />
          </div>
        </div>
        <label style={{ display:"flex", alignItems:"center", gap:8, cursor:"pointer", fontSize:13, color:"#111827", marginBottom:20 }}>
          <input type="checkbox" checked={form.whatsapp} onChange={e=>setForm({...form,whatsapp:e.target.checked})} /> Este telefone é WhatsApp
        </label>
        {/* Pagamento — a chave que se copia na hora de pagar. Fica no
            cadastro porque é sempre a mesma; a fatura pode trazer um
            copia-e-cola próprio, e aí é aquele que vale. */}
        <div style={{ marginBottom:6 }}>
          <div style={{ fontSize:11, fontWeight:700, color:"#4b5563", textTransform:"uppercase", letterSpacing:1 }}>Pagamento</div>
        </div>
        <div style={{ display:"grid", gridTemplateColumns:"160px 1fr", gap:12, marginBottom:12 }}>
          <div>
            <label style={PS.label}>Tipo da chave</label>
            <Selecao style={{ ...PS.input, cursor:"pointer" }} value={form.pixTipo || "cnpj"}
              onChange={e=>setForm({...form, pixTipo:e.target.value})}>
              {TIPOS_PIX.map(t => <option key={t.id} value={t.id}>{t.nome}</option>)}
            </Selecao>
          </div>
          <div>
            <label style={PS.label}>Chave PIX</label>
            <input style={PS.input} value={form.pixChave || ""} onChange={e=>setForm({...form, pixChave:e.target.value})}
              placeholder="00.000.000/0001-00" />
          </div>
        </div>
        <div style={{ marginBottom:14 }}>
          <label style={PS.label}>Beneficiário</label>
          <input style={PS.input} value={form.pixBeneficiario || ""} onChange={e=>setForm({...form, pixBeneficiario:e.target.value})}
            placeholder="quem aparece no aplicativo do banco — em branco, vale o nome do prestador" />
        </div>
        <div style={{ marginBottom:14 }}>
          <label style={PS.label}>Observações</label>
          <textarea style={{ ...PS.input, resize:"vertical" }} value={form.observacoes} onChange={e=>setForm({...form,observacoes:e.target.value})} rows={3} placeholder="Condições, indicações, alertas..." />
        </div>
        <label style={{ display:"flex", alignItems:"center", gap:8, cursor:"pointer", fontSize:13, color:"#111827", marginBottom:24 }}>
          <input type="checkbox" checked={form.ativo} onChange={e=>setForm({...form,ativo:e.target.checked})} /> Prestador ativo
        </label>
        <div style={{ display:"flex", gap:10, justifyContent:"flex-end" }}>
          <button type="button" style={PS.btnSec} onClick={()=>setView("list")}>Cancelar</button>
          <button type="submit" style={PS.btn}>{form.id ? "Salvar alterações" : "Cadastrar prestador"}</button>
        </div>
      </form>
    </div>
  );
}

